export interface WordEntry {
  word: string;
  meaning: string;
}

export interface DailyRecord {
  date: string; // YYYY-MM-DD
  page: string;
  words: WordEntry[];
  isCompleted: boolean;
}

export interface TestResult {
  word: string;
  userSpelling: string;
  userMeaning: string;
  isCorrect: boolean;
  feedback: string;
}

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const scoreTest = async (
  originalWord: string,
  originalMeaning: string,
  userSpelling: string,
  userMeaning: string
) => {
  const prompt = `
    You are an English teacher grading a middle school student's vocabulary test.
    Target Word: "${originalWord}"
    Target Meaning: "${originalMeaning}"
    Student's Spelling: "${userSpelling}"
    Student's Meaning: "${userMeaning}"

    Check if the spelling is exactly correct and if the meaning is synonymous or accurate.
    Provide a JSON response.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            isCorrect: { type: Type.BOOLEAN },
            feedback: { type: Type.STRING, description: "Short encouragement or correction in Korean" }
          },
          required: ["isCorrect", "feedback"]
        }
      }
    });

    return JSON.parse(response.text);
  } catch (error) {
    console.error("AI Scoring Error:", error);
    // Fallback simple check
    const spellingMatch = originalWord.toLowerCase().trim() === userSpelling.toLowerCase().trim();
    return {
      isCorrect: spellingMatch,
      feedback: spellingMatch ? "참 잘했어요!" : `아쉬워요. 정답은 ${originalWord}입니다.`
    };
  }
};

