const saveToGoogleSheet = async (record: DailyRecord) => {
  try {
    const response = await fetch(GAS_URL, {
      method: "POST",
      mode: "no-cors", // GAS requires no-cors for simple trigger if not handling redirect
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(record),
    });
    return true;
  } catch (error) {
    console.error("Error saving to Google Sheets:", error);
    return false;
  }
};

