  try {
    // text/plain content type helps avoid CORS preflight issues with GAS
    const response = await fetch(GAS_URL, {
      method: "POST",
      mode: "no-cors", 
      headers: {
        "Content-Type": "text/plain",
      },
      body: JSON.stringify(record),
    });
