            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
              <div className="flex justify-between items-center mb-4">
                <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                  <CalendarIcon className="w-6 h-6 text-indigo-500" />
                  {calendarData.year}년 {calendarData.month}월 학습 현황
                </h2>
              </div>
              <div className="grid grid-cols-7 gap-1 text-center">
                {['일','월','화','수','목','금','토'].map(d => (
                  <div key={d} className="text-[10px] font-bold text-slate-400 py-1">{d}</div>
                ))}
                {calendarData.days.map((dayObj, i) => {
                  if (!dayObj) return <div key={`empty-${i}`} className="aspect-square" />;

                  const isFinished = history.some(r => r.date === dayObj.dateStr && r.isCompleted);
                  const isToday = dayObj.dateStr === todayRecord.date;

                  return (
                    <div key={i} className={`aspect-square flex flex-col items-center justify-center relative rounded-xl border ${isToday ? 'border-indigo-400' : 'border-slate-50'} ${isFinished ? 'bg-green-50' : 'bg-slate-50'}`}>
                      <span className={`text-[11px] ${isFinished ? 'text-green-700 font-bold' : isToday ? 'text-indigo-600 font-bold' : 'text-slate-500'}`}>
                        {dayObj.day}
                      </span>
                      {isFinished && (
                        <div className="text-[8px] font-bold text-green-500 mt-0.5">완료</div>
                      )}
                    </div>
                  );
                })}
              </div>
            </div>
          </div>
        )}

        {activeTab === 'test' && (
          <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100 animate-fadeIn min-h-[400px] flex flex-col justify-center text-center">
            {testResults.length === 5 ? (
              <div className="space-y-6">
                <div className="w-20 h-20 bg-indigo-100 rounded-full flex items-center justify-center mx-auto mb-4">
                  <CheckCircleIcon className="w-12 h-12 text-indigo-600" />
                </div>
                <h2 className="text-2xl font-bold text-slate-800">테스트 종료!</h2>
                <div className="text-slate-500">
                  5문제 중 {testResults.filter(r => r.isCorrect).length}문제를 정복했습니다!
                </div>
                <div className="space-y-2 text-left overflow-y-auto max-h-[250px] pr-2">
                  {testResults.map((r, i) => (
                    <div key={i} className={`p-4 rounded-2xl border flex justify-between items-center ${r.isCorrect ? 'border-green-100 bg-green-50' : 'border-red-100 bg-red-50'}`}>
                      <div>
                        <p className="font-bold text-sm text-slate-800">{r.word}</p>
                        <p className="text-xs text-slate-500 leading-tight mt-1">{r.feedback}</p>
                      </div>
                      <span className={r.isCorrect ? 'text-green-600 text-xl' : 'text-red-600 text-xl'}>
                        {r.isCorrect ? '⭕' : '❌'}
                      </span>
                    </div>
                  ))}
                </div>
                <button 
                  onClick={startTest}
                  className="w-full bg-indigo-600 text-white font-bold py-4 rounded-2xl shadow-lg transition-all"
                >
                  새 테스트 시작
                </button>
              </div>
            ) : (
              <div className="space-y-8">
                <div>
                  <div className="text-xs font-bold text-slate-400 mb-2 uppercase tracking-widest">Question {testStep + 1} / 5</div>
                  <button 
                    onClick={() => speakWord(testWords[testStep].word)}
                    className="w-24 h-24 bg-indigo-50 hover:bg-indigo-100 rounded-full flex items-center justify-center mx-auto transition-all group"
                  >
                    <SpeakerWaveIcon className="w-10 h-10 text-indigo-600 group-hover:scale-110 transition-transform" />
                  </button>
                  <p className="mt-4 text-slate-500 text-sm">소리를 듣고 아래에 답을 적어주세요.</p>
                </div>

                <div className="space-y-4 max-w-sm mx-auto">
                  <input 
                    type="text"
                    placeholder="영어 단어"
                    autoFocus
                    value={currentTestInput.spelling}
                    onChange={(e) => setCurrentTestInput({...currentTestInput, spelling: e.target.value})}
                    className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl px-6 py-4 text-lg font-bold text-center focus:border-indigo-500 outline-none transition-all"
                  />
                  <input 
                    type="text"
                    placeholder="뜻"
                    value={currentTestInput.meaning}
                    onChange={(e) => setCurrentTestInput({...currentTestInput, meaning: e.target.value})}
                    className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl px-6 py-4 text-lg font-bold text-center focus:border-indigo-500 outline-none transition-all"
                  />
                </div>

                <button 
                  onClick={handleNextTest}
                  disabled={isScoring || !currentTestInput.spelling || !currentTestInput.meaning}
                  className="w-full max-w-sm mx-auto bg-slate-800 text-white font-bold py-4 rounded-2xl hover:bg-slate-900 disabled:opacity-50 transition-all flex items-center justify-center gap-2"
                >
                  {isScoring ? 'AI가 채점하는 중...' : '다음 문제 확인'}
                </button>
              </div>
            )}
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

payload.text:
구글 시트 연동이 되지 않고 달력 표시가 안 되는 문제를 해결하기 위해 코드를 전격 수정했습니다.

### (i) 업데이트 및 수정 사항
1.  **GAS URL 업데이트**: 요청하신 새로운 URL(`...1yqwA/exec`)로 변경했습니다.
2.  **전송 방식 최적화**: 구글 앱스 스크립트의 보안 정책(CORS) 문제를 피하기 위해 `text/plain` 방식으로 데이터를 안전하게 보냅니다.
3.  **달력 실시간 반영**: '제출' 버튼을 누르는 즉시 `history` 상태를 업데이트하여 달력에 즉각적으로 '완료' 표시가 나타나도록 로직을 개선했습니다.
4.  **로컬 날짜 고정**: UTC 기준이 아닌 사용자의 실제 오늘 날짜(한국 시간 등)를 정확히 계산하여 날짜가 어긋나지 않게 했습니다.
5.  **가이드 삭제**: 요청하신 대로 개발자 가이드 부분은 완전히 제거했습니다.

### (ii) 구글 시트 연동 방법 (학생용 쉬운 설명)
시트에 기록이 안 된다면, **구글 시트의 [확장 프로그램] -> [Apps Script]**에 들어있는 코드가 아래와 같은지 꼭 확인해 보세요!

```javascript
function doPost(e) {
  var data = JSON.parse(e.postData.contents);
  // 1. 시트 이름을 "영어단어"로 정확히 만들어주세요.
  var sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("영어단어");

  // 2. 단어 개수만큼 줄을 추가합니다.
  data.words.forEach(function(item) {
    if(item.word && item.word.trim() !== "") {
      sheet.appendRow([
        data.date,    // 날짜
        data.page,    // 페이지
        item.word,    // 영어단어
        item.meaning, // 의미
        "학습완료"     // 녹음기록(상태)
      ]);
    }
  });

  return ContentService.createTextOutput("성공").setMimeType(ContentService.MimeType.TEXT);
}
```
**중요**: 코드를 고친 후에는 반드시 **[배포] -> [새 배포] -> [액세스 권한: 모든 사용자(Anyone)]**로 설정해서 다시 배포해야 앱에서 시트로 문을 열고 들어갈 수 있습니다!

