                    <div key={i} className={`aspect-square flex flex-col items-center justify-center relative rounded-2xl border transition-all ${isFinished ? 'bg-green-50 border-green-200' : isToday ? 'bg-indigo-50 border-indigo-200' : 'bg-slate-50 border-slate-100'}`}>
                      <span className={`text-[11px] mb-0.5 ${isFinished ? 'text-green-700 font-bold' : isToday ? 'text-indigo-600 font-bold' : 'text-slate-500'}`}>
