                        <div className="w-1 h-1 bg-indigo-400 rounded-full mt-0.5 animate-pulse" />
                      )}
                    </div>
                  );
                })}
              </div>
            </div>
          </div>
        )}

        {activeTab === 'test' && (
          <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100 animate-fadeIn min-h-[450px] flex flex-col justify-center text-center">
            {testResults.length === 5 ? (
              <div className="space-y-6">
                <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-4">
                  <CheckCircleIcon className="w-12 h-12 text-green-600" />
                </div>
                <h2 className="text-2xl font-bold text-slate-800">테스트 결과</h2>
                <div className="text-slate-500">
                  총 5문제 중 <span className="text-indigo-600 font-bold">{testResults.filter(r => r.isCorrect).length}</span>문제를 맞혔습니다!
                </div>
                <div className="space-y-2 text-left overflow-y-auto max-h-[200px] pr-2 custom-scrollbar">
                  {testResults.map((r, i) => (
                    <div key={i} className={`p-4 rounded-2xl border flex justify-between items-center ${r.isCorrect ? 'border-green-100 bg-green-50' : 'border-red-100 bg-red-50'}`}>
                      <div className="flex-1">
