} from '@heroicons/react/24/outline';

// 새로운 GAS URL로 업데이트
const GAS_URL = "https://script.google.com/macros/s/AKfycbwik_1KKizN8tuV64JNi-A2y_ioU4VnGH54nk2CIxRblzhjLDzP9hydCx2O6EnsQKHOYQ/exec";

const getTodayString = () => {
  const now = new Date();
  const offset = now.getTimezoneOffset() * 60000;
  return new Date(now.getTime() - offset).toISOString().split('T')[0];
};

const saveToGoogleSheet = async (record: DailyRecord) => {
  try {
    // record 객체에 newsContent가 포함되어 전송됩니다.
    await fetch(GAS_URL, {
      method: "POST",
      mode: "no-cors", 
      headers: { "Content-Type": "text/plain" },
      body: JSON.stringify(record),
    });
    return true;
  } catch (error) {
    console.error("Error saving to Google Sheets:", error);
    return false;
  }
};

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'study' | 'test'>('study');
  const [testMode, setTestMode] = useState<'none' | 'today' | 'cumulative'>('none');
  const [todayRecord, setTodayRecord] = useState<DailyRecord>({
    date: getTodayString(),
    page: '',
    words: Array(13).fill({ word: '', meaning: '' }),
    newsContent: '',
    isCompleted: false,
  });
  const [history, setHistory] = useState<DailyRecord[]>([]);
  const [testWords, setTestWords] = useState<WordEntry[]>([]);
  const [testStep, setTestStep] = useState(0);
  const [testResults, setTestResults] = useState<TestResult[]>([]);
  const [currentTestInput, setCurrentTestInput] = useState({ spelling: '', meaning: '' });
  const [isScoring, setIsScoring] = useState(false);

  const calendarData = useMemo(() => {
    const now = new Date();
    const year = now.getFullYear();
    const month = now.getMonth();
    const firstDay = new Date(year, month, 1).getDay();
    const lastDate = new Date(year, month + 1, 0).getDate();
    const days = [];
    for (let i = 0; i < firstDay; i++) days.push(null);
    for (let i = 1; i <= lastDate; i++) {
      days.push({
        day: i,
        dateStr: `${year}-${String(month + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`
      });
    }
    return { days, month: month + 1, year };
  }, []);

  useEffect(() => {
    const saved = localStorage.getItem('study_history');
    if (saved) {
      const parsed: DailyRecord[] = JSON.parse(saved);
      setHistory(parsed);
      const todayInHistory = parsed.find(r => r.date === todayRecord.date);
      if (todayInHistory) setTodayRecord(todayInHistory);
    }
  }, [todayRecord.date]);

  const handleWordChange = (index: number, field: keyof WordEntry, value: string) => {
    const newWords = [...todayRecord.words];
    newWords[index] = { ...newWords[index], [field]: value };
    setTodayRecord({ ...todayRecord, words: newWords });
  };

  const submitStudy = async () => {
    const updatedRecord = { ...todayRecord, isCompleted: true };
    setTodayRecord(updatedRecord);
    const newHistory = [...history.filter(r => r.date !== todayRecord.date), updatedRecord];
    setHistory(newHistory);
    localStorage.setItem('study_history', JSON.stringify(newHistory));

    const success = await saveToGoogleSheet(updatedRecord);
    if (success) {
      alert('학습 내용 및 영자신문 기록이 시트로 전송되었습니다!');
    } else {
      alert('시트 전송 중 오류가 발생했습니다.');
    }
  };

  const startTest = (mode: 'today' | 'cumulative') => {
    let sourceWords: WordEntry[] = [];

    if (mode === 'today') {
      sourceWords = todayRecord.words.filter(w => w.word.trim() !== "" && w.meaning.trim() !== "");
      if (sourceWords.length === 0) {
        alert('오늘 입력한 단어가 없습니다!');
        return;
      }
    } else {
      sourceWords = history.flatMap(r => r.words).filter(w => w.word.trim() !== "" && w.meaning.trim() !== "");
      if (sourceWords.length < 5) {
        alert('누적된 단어가 부족합니다. (최소 5개 필요)');
        return;
      }
    }

    const shuffled = [...sourceWords].sort(() => 0.5 - Math.random());
    const finalWords = mode === 'today' ? shuffled : shuffled.slice(0, 5);

    setTestWords(finalWords);
    setTestStep(0);
    setTestResults([]);
    setCurrentTestInput({ spelling: '', meaning: '' });
    setTestMode(mode);
    setActiveTab('test');
  };

  const speakWord = (word: string) => {
    const utterance = new SpeechSynthesisUtterance(word);
    utterance.lang = 'en-US';
    window.speechSynthesis.speak(utterance);
  };

  const handleNextTest = async () => {
    setIsScoring(true);
    const target = testWords[testStep];
    const score = await scoreTest(target.word, target.meaning, currentTestInput.spelling, currentTestInput.meaning);

    const result: TestResult = {
      word: target.word,
      userSpelling: currentTestInput.spelling,
      userMeaning: currentTestInput.meaning,
      isCorrect: score.isCorrect,
      feedback: score.feedback
    };

    const newResults = [...testResults, result];
    setTestResults(newResults);
    setIsScoring(false);

    if (testStep < testWords.length - 1) {
      setTestStep(testStep + 1);
      setCurrentTestInput({ spelling: '', meaning: '' });
    }
  };

  return (
    <div className="min-h-screen pb-24 max-w-2xl mx-auto p-4 flex flex-col gap-6">
      <header className="flex flex-col gap-1 items-center py-6 bg-white rounded-3xl shadow-sm border border-slate-100">
        <h1 className="text-2xl font-bold text-indigo-600 flex items-center gap-2">
          <AcademicCapIcon className="w-8 h-8" />
          영어 학습 기록장
        </h1>
        <p className="text-slate-500 text-sm italic">My Daily Vocab Master</p>
      </header>

      <nav className="flex bg-white p-1 rounded-2xl shadow-sm border border-slate-100 sticky top-4 z-50">
        <button 
          onClick={() => { setActiveTab('study'); setTestMode('none'); }}
          className={`flex-1 flex flex-col items-center py-3 rounded-xl transition-all ${activeTab === 'study' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}
        >
          <PencilSquareIcon className="w-6 h-6" />
          <span className="text-xs mt-1 font-semibold">학습 및 기록</span>
        </button>
        <button 
          onClick={() => { setActiveTab('test'); setTestMode('none'); }}
          className={`flex-1 flex flex-col items-center py-3 rounded-xl transition-all ${activeTab === 'test' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}
        >
          <ArrowPathIcon className="w-6 h-6" />
          <span className="text-xs mt-1 font-semibold">단어테스트</span>
        </button>
      </nav>

      <main className="flex-1">
        {activeTab === 'study' && (
          <div className="flex flex-col gap-6 animate-fadeIn">
            {/* Today Record Header */}
            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 space-y-4">
               <div className="flex justify-between items-center">
                 <h2 className="text-lg font-bold text-slate-800">학습 정보</h2>
                 <span className={`px-4 py-1 rounded-full text-[11px] font-bold ${todayRecord.isCompleted ? 'bg-green-100 text-green-700' : 'bg-amber-100 text-amber-700'}`}>
                    {todayRecord.isCompleted ? '학습완료' : '학습중'}
                 </span>
               </div>
               <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">날짜</label>
                    <div className="text-sm font-semibold text-slate-700 px-1">{todayRecord.date}</div>
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">페이지</label>
                    <input 
                      type="text" 
                      placeholder="P.00"
                      disabled={todayRecord.isCompleted}
                      value={todayRecord.page}
                      onChange={(e) => setTodayRecord({...todayRecord, page: e.target.value})}
                      className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-1 text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
                    />
                  </div>
               </div>
            </div>

            {/* English Newspaper Section */}
            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 space-y-3">
              <h3 className="font-bold text-slate-700 flex items-center gap-2">
                <NewspaperIcon className="w-5 h-5 text-indigo-500" />
                영자신문 읽기 기록
              </h3>
              <textarea 
                placeholder="오늘 읽은 영자신문의 주요 문장이나 요약을 기록해 보세요..."
                disabled={todayRecord.isCompleted}
                value={todayRecord.newsContent}
                onChange={(e) => setTodayRecord({...todayRecord, newsContent: e.target.value})}
                className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm min-h-[100px] outline-none focus:ring-2 focus:ring-indigo-500 disabled:opacity-50 transition-all custom-scrollbar"
              />
            </div>

            {/* Word List */}
            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 space-y-3">
              <h3 className="font-bold text-slate-700 flex justify-between">오늘의 단어 (13개)</h3>
              <div className="grid grid-cols-1 gap-2">
                {todayRecord.words.map((w, idx) => (
                  <div key={idx} className="flex gap-2 items-center">
                    <span className="w-5 text-[10px] font-bold text-slate-300">{idx + 1}</span>
                    <input 
                      type="text"
                      placeholder="Word"
                      disabled={todayRecord.isCompleted}
                      value={w.word}
                      onChange={(e) => handleWordChange(idx, 'word', e.target.value)}
                      className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-indigo-500 disabled:opacity-50"
                    />
                    <input 
                      type="text"
                      placeholder="의미"
                      disabled={todayRecord.isCompleted}
                      value={w.meaning}
                      onChange={(e) => handleWordChange(idx, 'meaning', e.target.value)}
                      className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-indigo-500 disabled:opacity-50"
                    />
                  </div>
                ))}
              </div>
              <div className="pt-4">
                {todayRecord.isCompleted ? (
                  <button onClick={() => setTodayRecord({...todayRecord, isCompleted: false})} className="w-full bg-slate-100 hover:bg-slate-200 text-slate-600 font-bold py-4 rounded-2xl flex items-center justify-center gap-2 transition-all">
                    <PencilSquareIcon className="w-5 h-5" /> 수정하기
                  </button>
                ) : (
                  <button onClick={submitStudy} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-4 rounded-2xl shadow-lg flex items-center justify-center gap-2 transition-all">
                    <CheckCircleIcon className="w-5 h-5" /> 학습완료 제출
                  </button>
                )}
              </div>
            </div>

            {/* Calendar */}
            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
              <h2 className="text-lg font-bold mb-6 text-slate-800 flex items-center gap-2">
                <CalendarIcon className="w-6 h-6 text-indigo-500" />
                {calendarData.year}년 {calendarData.month}월 학습 달력
              </h2>
              <div className="grid grid-cols-7 gap-2 text-center">
                {['일','월','화','수','목','금','토'].map(d => (
                  <div key={d} className="text-[10px] font-bold text-slate-400 py-2 uppercase">{d}</div>
                ))}
                {calendarData.days.map((dayObj, i) => {
                  if (!dayObj) return <div key={`empty-${i}`} />;
                  const record = history.find(r => r.date === dayObj.dateStr);
                  const isFinished = record && record.isCompleted;
                  const isToday = dayObj.dateStr === getTodayString();
                  return (
                    <div key={i} className={`aspect-square flex flex-col items-center justify-center rounded-2xl border transition-all ${isFinished ? 'bg-green-50 border-green-200' : isToday ? 'bg-indigo-50 border-indigo-200' : 'bg-slate-50 border-slate-100'}`}>
                      <span className={`text-[11px] ${isFinished ? 'text-green-700 font-bold' : isToday ? 'text-indigo-600 font-bold' : 'text-slate-500'}`}>{dayObj.day}</span>
                      {isFinished && <div className="text-[8px] font-bold text-green-500 mt-0.5">완료</div>}
                    </div>
                  );
                })}
              </div>
            </div>
          </div>
        )}

        {activeTab === 'test' && (
          <div className="animate-fadeIn">
            {testMode === 'none' ? (
              <div className="grid grid-cols-1 gap-6">
                <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100 text-center space-y-4">
                  <div className="w-16 h-16 bg-indigo-50 rounded-2xl flex items-center justify-center mx-auto mb-2">
                    <BookOpenIcon className="w-10 h-10 text-indigo-600" />
                  </div>
                  <h2 className="text-xl font-bold text-slate-800">오늘의 단어 테스트</h2>
                  <p className="text-slate-500 text-sm">오늘 공부하고 기록한 단어들을 <br/>전부 복습하며 시험을 봅니다.</p>
                  <button 
                    onClick={() => startTest('today')}
                    className="w-full bg-indigo-600 text-white font-bold py-4 rounded-2xl hover:bg-indigo-700 transition-all shadow-md"
                  >
                    오늘의 단어 시험 시작
                  </button>
                </div>

                <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100 text-center space-y-4">
                  <div className="w-16 h-16 bg-violet-50 rounded-2xl flex items-center justify-center mx-auto mb-2">
                    <SparklesIcon className="w-10 h-10 text-violet-600" />
                  </div>
                  <h2 className="text-xl font-bold text-slate-800">누가기록 전체 테스트</h2>
                  <p className="text-slate-500 text-sm">지금까지 학습한 모든 단어 중 <br/>랜덤으로 5문제를 골라 실력을 확인합니다.</p>
                  <button 
                    onClick={() => startTest('cumulative')}
                    className="w-full bg-violet-600 text-white font-bold py-4 rounded-2xl hover:bg-violet-700 transition-all shadow-md"
                  >
                    누적 전체 시험 시작 (랜덤 5개)
                  </button>
                </div>
              </div>
            ) : (
              <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100 min-h-[500px] flex flex-col justify-center text-center relative overflow-hidden">
                {testResults.length === testWords.length ? (
                  <div className="space-y-6">
                    <h2 className="text-2xl font-bold text-slate-800">테스트 결과</h2>
                    <div className="text-slate-500">
                      총 {testWords.length}문제 중 <span className="font-bold text-indigo-600">{testResults.filter(r => r.isCorrect).length}</span>문제를 맞혔어요!
                    </div>
                    <div className="space-y-3 text-left overflow-y-auto max-h-[300px] pr-2 custom-scrollbar">
                      {testResults.map((r, i) => (
                        <div key={i} className={`p-4 rounded-2xl border flex justify-between items-center transition-all ${r.isCorrect ? 'border-green-100 bg-green-50' : 'border-red-100 bg-red-50'}`}>
                          <div className="flex-1">
                            <div className="flex items-center gap-2">
                               <p className="font-bold text-sm text-slate-800">{r.word}</p>
                               <span className="text-[10px] text-slate-400">내 답변: {r.userMeaning}</span>
                            </div>
                            <p className="text-[11px] text-slate-500 mt-1 italic leading-tight">{r.feedback}</p>
                          </div>
                          <span className="text-xl">{r.isCorrect ? '⭕' : '❌'}</span>
                        </div>
                      ))}
                    </div>
                    <button 
                      onClick={() => setTestMode('none')}
                      className="w-full bg-slate-800 text-white font-bold py-4 rounded-2xl shadow-lg hover:bg-slate-900 transition-all"
                    >
                      다른 테스트 도전하기
                    </button>
                  </div>
                ) : (
                  <div className="space-y-8">
                    {/* Progress bar */}
                    <div className="absolute top-0 left-0 w-full h-1.5 bg-slate-100">
                      <div 
                        className="h-full bg-indigo-500 transition-all duration-300" 
                        style={{ width: `${((testStep + 1) / testWords.length) * 100}%` }}
                      />
                    </div>

                    <div>
                      <div className="text-[10px] font-bold text-slate-300 mb-6 uppercase tracking-[0.2em]">Question {testStep + 1} / {testWords.length}</div>
                      <button 
                        onClick={() => speakWord(testWords[testStep].word)}
                        className="w-24 h-24 bg-indigo-50 hover:bg-indigo-100 rounded-full flex items-center justify-center mx-auto transition-all group active:scale-90"
                      >
                        <SpeakerWaveIcon className="w-10 h-10 text-indigo-600 group-hover:scale-110 transition-transform" />
                      </button>
                      <p className="mt-4 text-slate-400 text-sm">버튼을 눌러 소리를 들어보세요</p>
                    </div>

                    <div className="space-y-4 max-w-sm mx-auto">
                      <input 
                        type="text"
                        placeholder="Spelling (철자)"
                        autoFocus
                        value={currentTestInput.spelling}
                        onChange={(e) => setCurrentTestInput({...currentTestInput, spelling: e.target.value})}
                        className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl px-6 py-4 text-xl font-bold text-center focus:border-indigo-500 outline-none transition-all placeholder:text-slate-200"
                      />
                      <input 
                        type="text"
                        placeholder="뜻 (Korean Meaning)"
                        value={currentTestInput.meaning}
                        onChange={(e) => setCurrentTestInput({...currentTestInput, meaning: e.target.value})}
                        className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl px-6 py-4 text-xl font-bold text-center focus:border-indigo-500 outline-none transition-all placeholder:text-slate-200"
                      />
                    </div>

                    <button 
                      onClick={handleNextTest}
                      disabled={isScoring || !currentTestInput.spelling.trim() || !currentTestInput.meaning.trim()}
                      className="w-full max-w-sm mx-auto bg-slate-800 text-white font-bold py-4 rounded-2xl hover:bg-slate-900 disabled:bg-slate-200 disabled:text-slate-400 transition-all flex items-center justify-center gap-2 shadow-lg"
                    >
                      {isScoring ? (
                        <>
                          <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                          AI 선생님 채점 중...
                        </>
                      ) : '정답 확인 및 다음 문제'}
                    </button>
                  </div>
                )}
              </div>
            )}
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

{
  "name": "Smart English Study Log",
  "description": "A comprehensive English learning record app with AI-powered testing, 13-word daily tracking, and a progress calendar.",
  "requestFramePermissions": [
    "microphone"
  ]
}

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { WordEntry, DailyRecord, TestResult } from './types';
import { scoreTest } from './services/geminiService';
import { 
  CalendarIcon, 
  PencilSquareIcon, 
  CheckCircleIcon, 
  ArrowPathIcon,
  SpeakerWaveIcon,
  AcademicCapIcon,
  BookOpenIcon,
  SparklesIcon,
  NewspaperIcon,
  MicrophoneIcon,
  StopIcon,
  PlayIcon
} from '@heroicons/react/24/outline';

const GAS_URL = "https://script.google.com/macros/s/AKfycbwik_1KKizN8tuV64JNi-A2y_ioU4VnGH54nk2CIxRblzhjLDzP9hydCx2O6EnsQKHOYQ/exec";

const getTodayString = () => {
  const now = new Date();
  const offset = now.getTimezoneOffset() * 60000;
  return new Date(now.getTime() - offset).toISOString().split('T')[0];
};

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'study' | 'test' | 'record'>('study');
  const [testMode, setTestMode] = useState<'none' | 'today' | 'cumulative'>('none');
  const [todayRecord, setTodayRecord] = useState<DailyRecord>({
    date: getTodayString(),
    page: '',
    words: Array(13).fill({ word: '', meaning: '' }),
    newsContent: '',
    isCompleted: false,
  });
  const [history, setHistory] = useState<DailyRecord[]>([]);
  const [testWords, setTestWords] = useState<WordEntry[]>([]);
  const [testStep, setTestStep] = useState(0);
  const [testResults, setTestResults] = useState<TestResult[]>([]);
  const [currentTestInput, setCurrentTestInput] = useState({ spelling: '', meaning: '' });
  const [isScoring, setIsScoring] = useState(false);

  // Recording states
  const [isRecording, setIsRecording] = useState(false);
  const [audioUrl, setAudioUrl] = useState<string | null>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);

  const calendarData = useMemo(() => {
    const now = new Date();
    const year = now.getFullYear();
    const month = now.getMonth();
    const firstDay = new Date(year, month, 1).getDay();
    const lastDate = new Date(year, month + 1, 0).getDate();
    const days = [];
    for (let i = 0; i < firstDay; i++) days.push(null);
    for (let i = 1; i <= lastDate; i++) {
      days.push({
        day: i,
        dateStr: `${year}-${String(month + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`
      });
    }
    return { days, month: month + 1, year };
  }, []);

  useEffect(() => {
    const saved = localStorage.getItem('study_history');
    if (saved) {
      const parsed: DailyRecord[] = JSON.parse(saved);
      setHistory(parsed);
      loadRecordForDate(todayRecord.date, parsed);
    }
  }, []);

  const loadRecordForDate = (dateStr: string, currentHistory: DailyRecord[]) => {
    const existing = currentHistory.find(r => r.date === dateStr);
    if (existing) {
      setTodayRecord(existing);
    } else {
      setTodayRecord({
        date: dateStr,
        page: '',
        words: Array(13).fill({ word: '', meaning: '' }),
        newsContent: '',
        isCompleted: false,
      });
    }
  };

  const handleDateChange = (newDate: string) => {
    loadRecordForDate(newDate, history);
  };

  const handleWordChange = (index: number, field: keyof WordEntry, value: string) => {
    const newWords = [...todayRecord.words];
    newWords[index] = { ...newWords[index], [field]: value };
    setTodayRecord({ ...todayRecord, words: newWords });
  };

  const submitStudy = async () => {
    const updatedRecord = { ...todayRecord, isCompleted: true };
    setTodayRecord(updatedRecord);
    const newHistory = [...history.filter(r => r.date !== todayRecord.date), updatedRecord];
    setHistory(newHistory);
    localStorage.setItem('study_history', JSON.stringify(newHistory));

    try {
      await fetch(GAS_URL, {
        method: "POST",
        mode: "no-cors", 
        headers: { "Content-Type": "text/plain" },
        body: JSON.stringify(updatedRecord),
      });
      alert('학습 내용이 시트로 전송되었습니다!');
    } catch (error) {
      console.error("Error saving to Google Sheets:", error);
      alert('시트 전송 실패. 인터넷 연결을 확인하세요.');
    }
  };

  const startTest = (mode: 'today' | 'cumulative') => {
    let sourceWords: WordEntry[] = [];

    if (mode === 'today') {
      sourceWords = todayRecord.words.filter(w => w.word?.trim() !== "" && w.meaning?.trim() !== "");
      if (sourceWords.length === 0) {
        alert('오늘 입력한 단어가 없습니다!');
        return;
      }
    } else {
      // 모든 기록에서 유효한 단어들만 추출 (중복 제거 포함)
      const allWords = history.flatMap(r => r.words).filter(w => w.word?.trim() !== "" && w.meaning?.trim() !== "");
      // 단어 객체 자체의 중복 제거 (스펠링 기준)
      const uniqueWordsMap = new Map();
      allWords.forEach(w => uniqueWordsMap.set(w.word.toLowerCase().trim(), w));
      sourceWords = Array.from(uniqueWordsMap.values());

      if (sourceWords.length < 5) {
        alert(`누적된 단어가 부족합니다. (현재 ${sourceWords.length}개 / 최소 5개 필요)`);
        return;
      }
    }

    const shuffled = [...sourceWords].sort(() => 0.5 - Math.random());
    const finalWords = mode === 'today' ? shuffled : shuffled.slice(0, 5);

    setTestWords(finalWords);
    setTestStep(0);
    setTestResults([]);
    setCurrentTestInput({ spelling: '', meaning: '' });
    setTestMode(mode);
    setActiveTab('test');
  };

  const speakWord = (word: string) => {
    const utterance = new SpeechSynthesisUtterance(word);
    utterance.lang = 'en-US';
    window.speechSynthesis.speak(utterance);
  };

  const handleNextTest = async () => {
    setIsScoring(true);
    const target = testWords[testStep];
    const score = await scoreTest(target.word, target.meaning, currentTestInput.spelling, currentTestInput.meaning);

    const result: TestResult = {
      word: target.word,
      userSpelling: currentTestInput.spelling,
      userMeaning: currentTestInput.meaning,
      isCorrect: score.isCorrect,
      feedback: score.feedback
    };

    setTestResults([...testResults, result]);
    setIsScoring(false);

    if (testStep < testWords.length - 1) {
      setTestStep(testStep + 1);
      setCurrentTestInput({ spelling: '', meaning: '' });
    }
  };

  // Recording Logic
  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];

      mediaRecorder.ondataavailable = (event) => {
        audioChunksRef.current.push(event.data);
      };

      mediaRecorder.onstop = () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/wav' });
        const url = URL.createObjectURL(audioBlob);
        setAudioUrl(url);
      };

      mediaRecorder.start();
      setIsRecording(true);
    } catch (err) {
      console.error("Microphone access denied:", err);
      alert("마이크 접근 권한이 필요합니다.");
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      mediaRecorderRef.current.stream.getTracks().forEach(track => track.stop());
    }
  };

  return (
    <div className="min-h-screen pb-24 max-w-2xl mx-auto p-4 flex flex-col gap-6">
      <header className="flex flex-col gap-1 items-center py-6 bg-white rounded-3xl shadow-sm border border-slate-100">
        <h1 className="text-2xl font-bold text-indigo-600 flex items-center gap-2">
          <AcademicCapIcon className="w-8 h-8" />
          영어 학습 기록장
        </h1>
        <p className="text-slate-500 text-sm italic">Smart Vocab Master</p>
      </header>

      <nav className="flex bg-white p-1 rounded-2xl shadow-sm border border-slate-100 sticky top-4 z-50">
        <button 
          onClick={() => { setActiveTab('study'); setTestMode('none'); }}
          className={`flex-1 flex flex-col items-center py-3 rounded-xl transition-all ${activeTab === 'study' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}
        >
          <PencilSquareIcon className="w-6 h-6" />
          <span className="text-[10px] mt-1 font-bold">기록</span>
        </button>
        <button 
          onClick={() => { setActiveTab('test'); setTestMode('none'); }}
          className={`flex-1 flex flex-col items-center py-3 rounded-xl transition-all ${activeTab === 'test' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}
        >
          <ArrowPathIcon className="w-6 h-6" />
          <span className="text-[10px] mt-1 font-bold">테스트</span>
        </button>
        <button 
          onClick={() => { setActiveTab('record'); setTestMode('none'); }}
          className={`flex-1 flex flex-col items-center py-3 rounded-xl transition-all ${activeTab === 'record' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}
        >
          <MicrophoneIcon className="w-6 h-6" />
          <span className="text-[10px] mt-1 font-bold">녹음</span>
        </button>
      </nav>

      <main className="flex-1">
        {activeTab === 'study' && (
          <div className="flex flex-col gap-6 animate-fadeIn">
            {/* Today Record Header */}
            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 space-y-4">
               <div className="flex justify-between items-center">
                 <h2 className="text-lg font-bold text-slate-800">학습 정보</h2>
                 <span className={`px-4 py-1 rounded-full text-[11px] font-bold ${todayRecord.isCompleted ? 'bg-green-100 text-green-700' : 'bg-amber-100 text-amber-700'}`}>
                    {todayRecord.isCompleted ? '학습완료' : '학습중'}
                 </span>
               </div>
               <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">날짜 선택</label>
                    <input 
                      type="date"
                      value={todayRecord.date}
                      onChange={(e) => handleDateChange(e.target.value)}
                      className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-1 text-sm focus:ring-2 focus:ring-indigo-500 outline-none font-semibold text-slate-700"
                    />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">페이지</label>
                    <input 
                      type="text" 
                      placeholder="예: 10-15"
                      disabled={todayRecord.isCompleted}
                      value={todayRecord.page}
                      onChange={(e) => setTodayRecord({...todayRecord, page: e.target.value})}
                      className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-1 text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
                    />
                  </div>
               </div>
            </div>

            {/* English Newspaper Section */}
            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 space-y-3">
              <h3 className="font-bold text-slate-700 flex items-center gap-2">
                <NewspaperIcon className="w-5 h-5 text-indigo-500" />
                영자신문 읽기 기록
              </h3>
              <textarea 
                placeholder="오늘 읽은 기사의 내용을 자유롭게 적어보세요..."
                disabled={todayRecord.isCompleted}
                value={todayRecord.newsContent}
                onChange={(e) => setTodayRecord({...todayRecord, newsContent: e.target.value})}
                className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm min-h-[100px] outline-none focus:ring-2 focus:ring-indigo-500 disabled:opacity-50 transition-all"
              />
            </div>

            {/* Word List */}
            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 space-y-3">
              <h3 className="font-bold text-slate-700 flex justify-between">영어 단어 (13개)</h3>
              <div className="grid grid-cols-1 gap-2">
                {todayRecord.words.map((w, idx) => (
                  <div key={idx} className="flex gap-2 items-center">
                    <span className="w-5 text-[10px] font-bold text-slate-300">{idx + 1}</span>
                    <input 
                      type="text"
                      placeholder="English"
                      disabled={todayRecord.isCompleted}
                      value={w.word}
                      onChange={(e) => handleWordChange(idx, 'word', e.target.value)}
                      className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-indigo-500 disabled:opacity-50"
                    />
                    <input 
                      type="text"
                      placeholder="뜻"
                      disabled={todayRecord.isCompleted}
                      value={w.meaning}
                      onChange={(e) => handleWordChange(idx, 'meaning', e.target.value)}
                      className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-indigo-500 disabled:opacity-50"
                    />
                  </div>
                ))}
              </div>
              <div className="pt-4">
                {todayRecord.isCompleted ? (
                  <button onClick={() => setTodayRecord({...todayRecord, isCompleted: false})} className="w-full bg-slate-100 text-slate-600 font-bold py-4 rounded-2xl flex items-center justify-center gap-2">
                    <PencilSquareIcon className="w-5 h-5" /> 수정하기
                  </button>
                ) : (
                  <button onClick={submitStudy} className="w-full bg-indigo-600 text-white font-bold py-4 rounded-2xl shadow-lg flex items-center justify-center gap-2">
                    <CheckCircleIcon className="w-5 h-5" /> 학습완료 제출
                  </button>
                )}
              </div>
            </div>

            {/* Calendar */}
            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
              <h2 className="text-lg font-bold mb-6 text-slate-800 flex items-center gap-2">
                <CalendarIcon className="w-6 h-6 text-indigo-500" />
                학습 달력
              </h2>
              <div className="grid grid-cols-7 gap-2 text-center">
                {['일','월','화','수','목','금','토'].map(d => (
                  <div key={d} className="text-[10px] font-bold text-slate-400 py-2 uppercase">{d}</div>
                ))}
                {calendarData.days.map((dayObj, i) => {
                  if (!dayObj) return <div key={`empty-${i}`} />;
                  const record = history.find(r => r.date === dayObj.dateStr);
                  const isFinished = record && record.isCompleted;
                  const isSelected = dayObj.dateStr === todayRecord.date;
                  return (
                    <button 
                      key={i} 
                      onClick={() => handleDateChange(dayObj.dateStr)}
                      className={`aspect-square flex flex-col items-center justify-center rounded-2xl border transition-all ${isFinished ? 'bg-green-50 border-green-200' : isSelected ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-slate-50 border-slate-100 hover:bg-slate-100'}`}
                    >
                      <span className={`text-[11px] font-bold ${isSelected ? 'text-white' : isFinished ? 'text-green-700' : 'text-slate-500'}`}>{dayObj.day}</span>
                      {isFinished && !isSelected && <div className="text-[8px] font-bold text-green-500 mt-0.5">완료</div>}
                    </button>
                  );
                })}
              </div>
            </div>
          </div>
        )}

        {activeTab === 'test' && (
          <div className="animate-fadeIn">
            {testMode === 'none' ? (
              <div className="grid grid-cols-1 gap-6">
                <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100 text-center space-y-4">
                  <div className="w-16 h-16 bg-indigo-50 rounded-2xl flex items-center justify-center mx-auto mb-2">
                    <BookOpenIcon className="w-10 h-10 text-indigo-600" />
                  </div>
                  <h2 className="text-xl font-bold text-slate-800">오늘의 단어 테스트</h2>
                  <p className="text-slate-500 text-sm">현재 보고 있는 날짜({todayRecord.date})의 <br/>단어들로 시험을 봅니다.</p>
                  <button onClick={() => startTest('today')} className="w-full bg-indigo-600 text-white font-bold py-4 rounded-2xl shadow-lg">시험 시작</button>
                </div>

                <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100 text-center space-y-4">
                  <div className="w-16 h-16 bg-violet-50 rounded-2xl flex items-center justify-center mx-auto mb-2">
                    <SparklesIcon className="w-10 h-10 text-violet-600" />
                  </div>
                  <h2 className="text-xl font-bold text-slate-800">누가기록 전체 테스트</h2>
                  <p className="text-slate-500 text-sm">지금까지 저장한 모든 단어 중 <br/>랜덤으로 5문제를 출제합니다.</p>
                  <button onClick={() => startTest('cumulative')} className="w-full bg-violet-600 text-white font-bold py-4 rounded-2xl shadow-lg">전체 랜덤 시험 시작</button>
                </div>
              </div>
            ) : (
              <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100 min-h-[500px] flex flex-col justify-center text-center relative overflow-hidden">
                {testResults.length === testWords.length ? (
                  <div className="space-y-6">
                    <h2 className="text-2xl font-bold text-slate-800">테스트 결과</h2>
                    <div className="text-slate-500">정답: {testResults.filter(r => r.isCorrect).length} / {testWords.length}</div>
                    <div className="space-y-2 text-left overflow-y-auto max-h-[300px] pr-2">
                      {testResults.map((r, i) => (
                        <div key={i} className={`p-4 rounded-2xl border ${r.isCorrect ? 'bg-green-50' : 'bg-red-50'}`}>
                          <div className="flex justify-between font-bold text-sm">
                            <span>{r.word}</span>
                            <span>{r.isCorrect ? '⭕' : '❌'}</span>
                          </div>
                          <p className="text-xs text-slate-500 mt-1">{r.feedback}</p>
                        </div>
                      ))}
                    </div>
                    <button onClick={() => setTestMode('none')} className="w-full bg-slate-800 text-white font-bold py-4 rounded-2xl">뒤로 가기</button>
                  </div>
                ) : (
                  <div className="space-y-8">
                    <div className="absolute top-0 left-0 w-full h-1.5 bg-slate-100">
                      <div className="h-full bg-indigo-500 transition-all" style={{ width: `${((testStep + 1) / testWords.length) * 100}%` }} />
                    </div>
                    <div>
                      <div className="text-xs font-bold text-slate-300 mb-6 uppercase">Question {testStep + 1}</div>
                      <button onClick={() => speakWord(testWords[testStep].word)} className="w-24 h-24 bg-indigo-50 rounded-full flex items-center justify-center mx-auto transition-transform active:scale-95">
                        <SpeakerWaveIcon className="w-10 h-10 text-indigo-600" />
                      </button>
                    </div>
                    <div className="space-y-4 max-w-sm mx-auto">
                      <input type="text" placeholder="Spelling" value={currentTestInput.spelling} onChange={(e) => setCurrentTestInput({...currentTestInput, spelling: e.target.value})} className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-6 py-4 text-center text-xl font-bold outline-none focus:ring-2 focus:ring-indigo-500" />
                      <input type="text" placeholder="뜻" value={currentTestInput.meaning} onChange={(e) => setCurrentTestInput({...currentTestInput, meaning: e.target.value})} className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-6 py-4 text-center text-xl font-bold outline-none focus:ring-2 focus:ring-indigo-500" />
                    </div>
                    <button onClick={handleNextTest} disabled={isScoring} className="w-full max-w-sm mx-auto bg-indigo-600 text-white font-bold py-4 rounded-2xl shadow-lg">
                      {isScoring ? 'AI 채점 중...' : '다음 문제'}
                    </button>
                  </div>
                )}
              </div>
            )}
          </div>
        )}

        {activeTab === 'record' && (
          <div className="animate-fadeIn flex flex-col gap-6">
            <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100 text-center space-y-6">
              <div className={`w-24 h-24 rounded-full flex items-center justify-center mx-auto transition-all ${isRecording ? 'bg-red-100 animate-pulse' : 'bg-indigo-50'}`}>
                <MicrophoneIcon className={`w-12 h-12 ${isRecording ? 'text-red-600' : 'text-indigo-600'}`} />
              </div>
              <div>
                <h2 className="text-xl font-bold text-slate-800">영어 발음 녹음하기</h2>
                <p className="text-slate-500 text-sm mt-1">오늘 배운 단어나 문장을 큰 소리로 읽어보세요.</p>
              </div>

              <div className="flex gap-4 justify-center">
                {!isRecording ? (
                  <button 
                    onClick={startRecording}
                    className="flex items-center gap-2 bg-indigo-600 text-white font-bold px-8 py-4 rounded-2xl shadow-lg hover:bg-indigo-700 transition-all"
                  >
                    <MicrophoneIcon className="w-5 h-5" /> 녹음 시작
                  </button>
                ) : (
                  <button 
                    onClick={stopRecording}
                    className="flex items-center gap-2 bg-red-600 text-white font-bold px-8 py-4 rounded-2xl shadow-lg hover:bg-red-700 transition-all"
                  >
                    <StopIcon className="w-5 h-5" /> 녹음 중지
                  </button>
                )}
              </div>

              {audioUrl && !isRecording && (
                <div className="pt-6 border-t border-slate-100 space-y-4">
                  <p className="text-xs font-bold text-slate-400 uppercase">최근 녹음 기록</p>
                  <div className="flex items-center justify-center gap-4">
                    <button 
                      onClick={() => {
                        const audio = new Audio(audioUrl);
                        audio.play();
                      }}
                      className="flex items-center gap-2 bg-slate-800 text-white font-bold px-6 py-3 rounded-xl shadow hover:bg-slate-900 transition-all"
                    >
                      <PlayIcon className="w-5 h-5" /> 녹음 들어보기
                    </button>
                    <button 
                      onClick={() => setAudioUrl(null)}
                      className="text-slate-400 text-xs font-bold hover:text-red-500 underline"
                    >
                      기록 삭제
                    </button>
                  </div>
                  <p className="text-[10px] text-slate-400">※ 녹음본은 브라우저 캐시에 임시 저장되며 새로고침 시 사라집니다.</p>
                </div>
              )}
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { WordEntry, DailyRecord, TestResult } from './types';
import { scoreTest } from './services/geminiService';
import { 
  CalendarIcon, 
  PencilSquareIcon, 
  CheckCircleIcon, 
  ArrowPathIcon,
  SpeakerWaveIcon,
  AcademicCapIcon,
  BookOpenIcon,
  SparklesIcon,
  NewspaperIcon,
  MicrophoneIcon,
  StopIcon,
  PlayIcon
} from '@heroicons/react/24/outline';

// 최신 GAS URL 적용
const GAS_URL = "https://script.google.com/macros/s/AKfycbyPJsDByc9jma_YM-pPizmJfNt3QpYjDGHoqw89gJCMe0xMGIN5rncRhFvaXaHba79U-A/exec";

const getTodayString = () => {
  const now = new Date();
  const offset = now.getTimezoneOffset() * 60000;
  return new Date(now.getTime() - offset).toISOString().split('T')[0];
};

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'study' | 'test' | 'record'>('study');
  const [testMode, setTestMode] = useState<'none' | 'today' | 'cumulative'>('none');
  const [todayRecord, setTodayRecord] = useState<DailyRecord>({
    date: getTodayString(),
    page: '',
    words: Array(13).fill({ word: '', meaning: '' }),
    newsContent: '',
    isCompleted: false,
  });
  const [history, setHistory] = useState<DailyRecord[]>([]);
  const [testWords, setTestWords] = useState<WordEntry[]>([]);
  const [testStep, setTestStep] = useState(0);
  const [testResults, setTestResults] = useState<TestResult[]>([]);
  const [currentTestInput, setCurrentTestInput] = useState({ spelling: '', meaning: '' });
  const [isScoring, setIsScoring] = useState(false);

  // Recording states
  const [isRecording, setIsRecording] = useState(false);
  const [audioUrl, setAudioUrl] = useState<string | null>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);

  const calendarData = useMemo(() => {
    const now = new Date();
    const year = now.getFullYear();
    const month = now.getMonth();
    const firstDay = new Date(year, month, 1).getDay();
    const lastDate = new Date(year, month + 1, 0).getDate();
    const days = [];
    for (let i = 0; i < firstDay; i++) days.push(null);
    for (let i = 1; i <= lastDate; i++) {
      days.push({
        day: i,
        dateStr: `${year}-${String(month + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`
      });
    }
    return { days, month: month + 1, year };
  }, []);

  // 초기 로딩
  useEffect(() => {
    const saved = localStorage.getItem('study_history');
    if (saved) {
      const parsed: DailyRecord[] = JSON.parse(saved);
      setHistory(parsed);
      loadRecordForDate(todayRecord.date, parsed);
    }
  }, []);

  const loadRecordForDate = (dateStr: string, currentHistory: DailyRecord[]) => {
    const existing = currentHistory.find(r => r.date === dateStr);
    if (existing) {
      setTodayRecord(existing);
    } else {
      setTodayRecord({
        date: dateStr,
        page: '',
        words: Array(13).fill({ word: '', meaning: '' }),
        newsContent: '',
        isCompleted: false,
      });
    }
  };

  const handleDateChange = (newDate: string) => {
    loadRecordForDate(newDate, history);
  };

  const handleWordChange = (index: number, field: keyof WordEntry, value: string) => {
    const newWords = [...todayRecord.words];
    newWords[index] = { ...newWords[index], [field]: value };
    setTodayRecord({ ...todayRecord, words: newWords });
  };

  const submitStudy = async () => {
    const updatedRecord = { ...todayRecord, isCompleted: true };
    setTodayRecord(updatedRecord);
    const newHistory = [...history.filter(r => r.date !== todayRecord.date), updatedRecord];
    setHistory(newHistory);
    localStorage.setItem('study_history', JSON.stringify(newHistory));

    try {
      await fetch(GAS_URL, {
        method: "POST",
        mode: "no-cors", 
        headers: { "Content-Type": "text/plain" },
        body: JSON.stringify(updatedRecord),
      });
      alert('학습 내용이 구글 시트로 성공적으로 전송되었습니다!');
    } catch (error) {
      console.error("Error saving to Google Sheets:", error);
      alert('시트 전송 중 오류가 발생했습니다. (데이터는 브라우저에 저장되었습니다)');
    }
  };

  const startTest = (mode: 'today' | 'cumulative') => {
    let sourceWords: WordEntry[] = [];

    if (mode === 'today') {
      // 오늘 현재 화면에 있는 단어들 필터링
      sourceWords = todayRecord.words.filter(w => w && w.word?.trim() !== "" && w.meaning?.trim() !== "");
      if (sourceWords.length === 0) {
        alert('오늘 학습 정보에 입력된 단어가 없습니다!');
        return;
      }
    } else {
      // 1. 과거 히스토리 전체 단어 추출
      const historyWords = history.flatMap(r => r.words || []);
      // 2. 오늘 입력 중인 단어도 포함
      const currentWords = todayRecord.words || [];

      const allPossibleWords = [...historyWords, ...currentWords].filter(w => 
        w && typeof w.word === 'string' && w.word.trim() !== "" && 
        w.meaning && typeof w.meaning === 'string' && w.meaning.trim() !== ""
      );

      // 중복 제거 (대소문자 무시)
      const uniqueWordsMap = new Map();
      allPossibleWords.forEach(w => {
        const key = w.word.toLowerCase().trim();
        if (!uniqueWordsMap.has(key)) {
          uniqueWordsMap.set(key, w);
        }
      });

      sourceWords = Array.from(uniqueWordsMap.values());

      if (sourceWords.length === 0) {
        alert('테스트할 누적 단어가 하나도 없습니다. 먼저 단어를 입력하고 저장해 주세요!');
        return;
      }
    }

    // 문제 섞기
    const shuffled = [...sourceWords].sort(() => 0.5 - Math.random());
    // 전체 테스트는 최대 5개, 오늘 테스트는 입력한 만큼
    const finalWords = mode === 'today' ? shuffled : shuffled.slice(0, Math.min(5, shuffled.length));

    setTestWords(finalWords);
    setTestStep(0);
    setTestResults([]);
    setCurrentTestInput({ spelling: '', meaning: '' });
    setTestMode(mode);
    setActiveTab('test');
  };

  const speakWord = (word: string) => {
    const utterance = new SpeechSynthesisUtterance(word);
    utterance.lang = 'en-US';
    window.speechSynthesis.speak(utterance);
  };

  const handleNextTest = async () => {
    if (isScoring) return;

    setIsScoring(true);
    const target = testWords[testStep];
    const score = await scoreTest(target.word, target.meaning, currentTestInput.spelling, currentTestInput.meaning);

    const result: TestResult = {
      word: target.word,
      userSpelling: currentTestInput.spelling,
      userMeaning: currentTestInput.meaning,
      isCorrect: score.isCorrect,
      feedback: score.feedback
    };

    const newResults = [...testResults, result];
    setTestResults(newResults);
    setIsScoring(false);

    if (testStep < testWords.length - 1) {
      setTestStep(testStep + 1);
      setCurrentTestInput({ spelling: '', meaning: '' });
    }
  };

  // Recording Logic
  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];

      mediaRecorder.ondataavailable = (event) => {
        if (event.data.size > 0) audioChunksRef.current.push(event.data);
      };

      mediaRecorder.onstop = () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/wav' });
        const url = URL.createObjectURL(audioBlob);
        setAudioUrl(url);
      };

      mediaRecorder.start();
      setIsRecording(true);
    } catch (err) {
      console.error("Microphone access denied:", err);
      alert("마이크 접근 권한이 필요합니다. 브라우저 설정을 확인해주세요.");
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      mediaRecorderRef.current.stream.getTracks().forEach(track => track.stop());
    }
  };

  return (
    <div className="min-h-screen pb-24 max-w-2xl mx-auto p-4 flex flex-col gap-6">
      <header className="flex flex-col gap-1 items-center py-6 bg-white rounded-3xl shadow-sm border border-slate-100">
        <h1 className="text-2xl font-bold text-indigo-600 flex items-center gap-2">
          <AcademicCapIcon className="w-8 h-8" />
          영어 학습 기록장
        </h1>
        <p className="text-slate-500 text-sm italic">My Daily Learning Partner</p>
      </header>

      <nav className="flex bg-white p-1 rounded-2xl shadow-sm border border-slate-100 sticky top-4 z-50">
        <button 
          onClick={() => { setActiveTab('study'); setTestMode('none'); }}
          className={`flex-1 flex flex-col items-center py-3 rounded-xl transition-all ${activeTab === 'study' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}
        >
          <PencilSquareIcon className="w-6 h-6" />
          <span className="text-[10px] mt-1 font-bold">기록/수정</span>
        </button>
        <button 
          onClick={() => { setActiveTab('test'); setTestMode('none'); }}
          className={`flex-1 flex flex-col items-center py-3 rounded-xl transition-all ${activeTab === 'test' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}
        >
          <ArrowPathIcon className="w-6 h-6" />
          <span className="text-[10px] mt-1 font-bold">테스트</span>
        </button>
        <button 
          onClick={() => { setActiveTab('record'); setTestMode('none'); }}
          className={`flex-1 flex flex-col items-center py-3 rounded-xl transition-all ${activeTab === 'record' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}
        >
          <MicrophoneIcon className="w-6 h-6" />
          <span className="text-[10px] mt-1 font-bold">발음 녹음</span>
        </button>
      </nav>

      <main className="flex-1">
        {activeTab === 'study' && (
          <div className="flex flex-col gap-6 animate-fadeIn">
            {/* 학습 정보 섹션 */}
            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 space-y-4">
               <div className="flex justify-between items-center">
                 <h2 className="text-lg font-bold text-slate-800">학습 정보</h2>
                 <span className={`px-4 py-1 rounded-full text-[11px] font-bold ${todayRecord.isCompleted ? 'bg-green-100 text-green-700' : 'bg-amber-100 text-amber-700'}`}>
                    {todayRecord.isCompleted ? '학습완료' : '학습중'}
                 </span>
               </div>
               <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">날짜 선택</label>
                    <input 
                      type="date"
                      value={todayRecord.date}
                      onChange={(e) => handleDateChange(e.target.value)}
                      className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-1 text-sm focus:ring-2 focus:ring-indigo-500 outline-none font-bold text-slate-700"
                    />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">페이지</label>
                    <input 
                      type="text" 
                      placeholder="예: 10~25"
                      disabled={todayRecord.isCompleted}
                      value={todayRecord.page}
                      onChange={(e) => setTodayRecord({...todayRecord, page: e.target.value})}
                      className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-1 text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
                    />
                  </div>
               </div>
            </div>

            {/* 영자신문 섹션 */}
            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 space-y-3">
              <h3 className="font-bold text-slate-700 flex items-center gap-2">
                <NewspaperIcon className="w-5 h-5 text-indigo-500" />
                영자신문 읽기 기록
              </h3>
              <textarea 
                placeholder="오늘 읽은 기사의 요약이나 중요한 문장을 기록해보세요..."
                disabled={todayRecord.isCompleted}
                value={todayRecord.newsContent}
                onChange={(e) => setTodayRecord({...todayRecord, newsContent: e.target.value})}
                className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm min-h-[100px] outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
              />
            </div>

            {/* 단어 입력 리스트 */}
            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 space-y-3">
              <h3 className="font-bold text-slate-700">오늘의 단어 (13개)</h3>
              <div className="grid grid-cols-1 gap-2">
                {todayRecord.words.map((w, idx) => (
                  <div key={idx} className="flex gap-2 items-center">
                    <span className="w-5 text-[10px] font-bold text-slate-300">{idx + 1}</span>
                    <input 
                      type="text"
                      placeholder="Word"
                      disabled={todayRecord.isCompleted}
                      value={w.word}
                      onChange={(e) => handleWordChange(idx, 'word', e.target.value)}
                      className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-indigo-500 disabled:opacity-50"
                    />
                    <input 
                      type="text"
                      placeholder="의미"
                      disabled={todayRecord.isCompleted}
                      value={w.meaning}
                      onChange={(e) => handleWordChange(idx, 'meaning', e.target.value)}
                      className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-indigo-500 disabled:opacity-50"
                    />
                  </div>
                ))}
              </div>
              <div className="pt-4">
                {todayRecord.isCompleted ? (
                  <button onClick={() => setTodayRecord({...todayRecord, isCompleted: false})} className="w-full bg-slate-100 text-slate-600 font-bold py-4 rounded-2xl flex items-center justify-center gap-2 hover:bg-slate-200 transition-all">
                    <PencilSquareIcon className="w-5 h-5" /> 수정하기
                  </button>
                ) : (
                  <button onClick={submitStudy} className="w-full bg-indigo-600 text-white font-bold py-4 rounded-2xl shadow-lg flex items-center justify-center gap-2 hover:bg-indigo-700 transition-all">
                    <CheckCircleIcon className="w-5 h-5" /> 학습완료 제출
                  </button>
                )}
              </div>
            </div>

            {/* 학습 달력 */}
            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
              <h2 className="text-lg font-bold mb-6 text-slate-800 flex items-center gap-2">
                <CalendarIcon className="w-6 h-6 text-indigo-500" />
                학습 달력
              </h2>
              <div className="grid grid-cols-7 gap-2 text-center">
                {['일','월','화','수','목','금','토'].map(d => (
                  <div key={d} className="text-[10px] font-bold text-slate-400 py-2 uppercase">{d}</div>
                ))}
                {calendarData.days.map((dayObj, i) => {
                  if (!dayObj) return <div key={`empty-${i}`} />;
                  const record = history.find(r => r.date === dayObj.dateStr);
                  const isFinished = record && record.isCompleted;
                  const isSelected = dayObj.dateStr === todayRecord.date;
                  return (
                    <button 
                      key={i} 
                      onClick={() => handleDateChange(dayObj.dateStr)}
                      className={`aspect-square flex flex-col items-center justify-center rounded-2xl border transition-all ${isFinished ? 'bg-green-50 border-green-200' : isSelected ? 'bg-indigo-600 border-indigo-600 text-white shadow-md scale-105' : 'bg-slate-50 border-slate-100 hover:bg-slate-100'}`}
                    >
                      <span className={`text-[11px] font-bold ${isSelected ? 'text-white' : isFinished ? 'text-green-700' : 'text-slate-500'}`}>{dayObj.day}</span>
                      {isFinished && !isSelected && <div className="text-[7px] font-bold text-green-500 mt-0.5">완료</div>}
                    </button>
                  );
                })}
              </div>
            </div>
          </div>
        )}

        {activeTab === 'test' && (
          <div className="animate-fadeIn">
            {testMode === 'none' ? (
              <div className="grid grid-cols-1 gap-6">
                <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100 text-center space-y-4">
                  <div className="w-16 h-16 bg-indigo-50 rounded-2xl flex items-center justify-center mx-auto mb-2">
                    <BookOpenIcon className="w-10 h-10 text-indigo-600" />
                  </div>
                  <h2 className="text-xl font-bold text-slate-800">오늘의 단어 테스트</h2>
                  <p className="text-slate-500 text-sm">현재 선택된 날짜({todayRecord.date})에 <br/>입력된 모든 단어를 시험봅니다.</p>
                  <button onClick={() => startTest('today')} className="w-full bg-indigo-600 text-white font-bold py-4 rounded-2xl shadow-lg hover:bg-indigo-700 transition-all">시험 시작</button>
                </div>

                <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100 text-center space-y-4">
                  <div className="w-16 h-16 bg-violet-50 rounded-2xl flex items-center justify-center mx-auto mb-2">
                    <SparklesIcon className="w-10 h-10 text-violet-600" />
                  </div>
                  <h2 className="text-xl font-bold text-slate-800">누가기록 전체 테스트</h2>
                  <p className="text-slate-500 text-sm">지금까지 저장한 모든 단어 중에서 <br/>랜덤으로 최대 5문제를 골라 시험봅니다.</p>
                  <button onClick={() => startTest('cumulative')} className="w-full bg-violet-600 text-white font-bold py-4 rounded-2xl shadow-lg hover:bg-violet-700 transition-all">전체 랜덤 시험 시작</button>
                </div>
              </div>
            ) : (
              <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100 min-h-[500px] flex flex-col justify-center text-center relative overflow-hidden">
                {testResults.length === testWords.length ? (
                  <div className="space-y-6">
                    <h2 className="text-2xl font-bold text-slate-800">테스트 결과</h2>
                    <div className="text-lg text-slate-600">
                      정답 개수: <span className="font-bold text-indigo-600">{testResults.filter(r => r.isCorrect).length}</span> / {testWords.length}
                    </div>
                    <div className="space-y-2 text-left overflow-y-auto max-h-[300px] pr-2 custom-scrollbar">
                      {testResults.map((r, i) => (
                        <div key={i} className={`p-4 rounded-2xl border transition-all ${r.isCorrect ? 'bg-green-50 border-green-100' : 'bg-red-50 border-red-100'}`}>
                          <div className="flex justify-between font-bold text-sm text-slate-800">
                            <span>{r.word}</span>
                            <span>{r.isCorrect ? '⭕ 정답' : '❌ 오답'}</span>
                          </div>
                          <p className="text-xs text-slate-500 mt-1">{r.feedback}</p>
                        </div>
                      ))}
                    </div>
                    <button onClick={() => setTestMode('none')} className="w-full bg-slate-800 text-white font-bold py-4 rounded-2xl shadow-md hover:bg-slate-900 transition-all">테스트 종료 및 돌아가기</button>
                  </div>
                ) : (
                  <div className="space-y-8">
                    {/* 진행 바 */}
                    <div className="absolute top-0 left-0 w-full h-1.5 bg-slate-100">
                      <div className="h-full bg-indigo-500 transition-all duration-300" style={{ width: `${((testStep + 1) / testWords.length) * 100}%` }} />
                    </div>
                    <div>
                      <div className="text-xs font-bold text-slate-300 mb-6 uppercase tracking-widest">Question {testStep + 1} / {testWords.length}</div>
                      <button onClick={() => speakWord(testWords[testStep].word)} className="w-24 h-24 bg-indigo-50 rounded-full flex items-center justify-center mx-auto transition-all hover:bg-indigo-100 active:scale-95 group">
                        <SpeakerWaveIcon className="w-10 h-10 text-indigo-600 group-hover:scale-110 transition-transform" />
                      </button>
                      <p className="mt-4 text-slate-400 text-xs">스피커 버튼을 눌러 소리를 들으세요</p>
                    </div>
                    <div className="space-y-4 max-w-sm mx-auto">
                      <input 
                        type="text" 
                        placeholder="English Spelling" 
                        value={currentTestInput.spelling} 
                        onChange={(e) => setCurrentTestInput({...currentTestInput, spelling: e.target.value})} 
                        className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-6 py-4 text-center text-xl font-bold outline-none focus:ring-2 focus:ring-indigo-500" 
                      />
                      <input 
                        type="text" 
                        placeholder="한글 뜻" 
                        value={currentTestInput.meaning} 
                        onChange={(e) => setCurrentTestInput({...currentTestInput, meaning: e.target.value})} 
                        className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-6 py-4 text-center text-xl font-bold outline-none focus:ring-2 focus:ring-indigo-500" 
                      />
                    </div>
                    <button 
                      onClick={handleNextTest} 
                      disabled={isScoring || !currentTestInput.spelling.trim() || !currentTestInput.meaning.trim()} 
                      className="w-full max-w-sm mx-auto bg-indigo-600 text-white font-bold py-4 rounded-2xl shadow-lg disabled:bg-slate-200 disabled:text-slate-400 flex items-center justify-center gap-2"
                    >
                      {isScoring ? (
                        <>
                          <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                          AI 선생님 채점 중...
                        </>
                      ) : '정답 확인 및 다음 문제'}
                    </button>
                  </div>
                )}
              </div>
            )}
          </div>
        )}

        {activeTab === 'record' && (
          <div className="animate-fadeIn flex flex-col gap-6">
            <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100 text-center space-y-6">
              <div className={`w-24 h-24 rounded-full flex items-center justify-center mx-auto transition-all ${isRecording ? 'bg-red-100 animate-pulse' : 'bg-indigo-50'}`}>
                <MicrophoneIcon className={`w-12 h-12 ${isRecording ? 'text-red-600' : 'text-indigo-600'}`} />
              </div>
              <div>
                <h2 className="text-xl font-bold text-slate-800">영어 발음 연습</h2>
                <p className="text-slate-500 text-sm mt-1">오늘 배운 주요 단어나 문장을 읽고 녹음해보세요.</p>
              </div>

              <div className="flex gap-4 justify-center">
                {!isRecording ? (
                  <button 
                    onClick={startRecording}
                    className="flex items-center gap-2 bg-indigo-600 text-white font-bold px-8 py-4 rounded-2xl shadow-lg hover:bg-indigo-700 transition-all"
                  >
                    <MicrophoneIcon className="w-5 h-5" /> 녹음 시작
                  </button>
                ) : (
                  <button 
                    onClick={stopRecording}
                    className="flex items-center gap-2 bg-red-600 text-white font-bold px-8 py-4 rounded-2xl shadow-lg hover:bg-red-700 transition-all"
                  >
                    <StopIcon className="w-5 h-5" /> 녹음 중지
                  </button>
                )}
              </div>

              {audioUrl && !isRecording && (
                <div className="pt-6 border-t border-slate-100 space-y-4">
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">내 녹음 들어보기</p>
                  <div className="flex items-center justify-center gap-4">
                    <button 
                      onClick={() => {
                        const audio = new Audio(audioUrl);
                        audio.play();
                      }}
                      className="flex items-center gap-2 bg-slate-800 text-white font-bold px-6 py-3 rounded-xl shadow-md hover:bg-slate-900 transition-all"
                    >
                      <PlayIcon className="w-5 h-5" /> 재생하기
                    </button>
                    <button 
                      onClick={() => {
                        URL.revokeObjectURL(audioUrl);
                        setAudioUrl(null);
                      }}
                      className="text-slate-400 text-xs font-bold hover:text-red-500 underline underline-offset-4"
                    >
                      삭제
                    </button>
                  </div>
                  <p className="text-[9px] text-slate-400">※ 녹음은 브라우저를 닫거나 새로고침하면 사라집니다.</p>
                </div>
              )}
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

payload.text:
구글 시트에 기록된 전체 단어 데이터를 불러와서 테스트에 활용할 수 있도록 **데이터 동기화(Sync) 기능**을 추가하고, **누적 테스트 로직**을 시트 데이터 중심으로 수정했습니다.

### (i) 업데이트 및 수정 사항
1.  **시트 데이터 불러오기(GET) 기능 추가**: 
    *   앱이 시작될 때 구글 시트에서 기존에 기록된 모든 단어("영어단어", "의미" 헤더 아래의 데이터)를 자동으로 가져옵니다.
    *   이제 `localStorage`뿐만 아니라 실제 구글 시트에 있는 데이터를 기반으로 시험이 출제됩니다.
2.  **누적 테스트 버튼(Cumulative Test) 수리**:
    *   버튼이 작동하지 않던 원인은 테스트 후보 단어를 추출하는 과정에서 데이터 형식이 맞지 않거나 `history`가 비어있을 때의 예외 처리가 부족했기 때문입니다. 
    *   시트에서 가져온 전체 단어 뭉치에서 **랜덤하게 5개를 추출**하는 로직을 더 강력하게 수정했습니다.
3.  **데이터 통합 로직**:
