                    </div>
                    <button onClick={handleNextTest} disabled={isScoring || !currentTestInput.spelling.trim() || !currentTestInput.meaning.trim()} className="w-full max-w-sm mx-auto bg-indigo-600 text-white font-bold py-4 rounded-2xl shadow-lg">
                      {isScoring ? '채점 중...' : '다음 문제'}
                    </button>
                  </div>
                )}
              </div>
            )}
          </div>
        )}

        {activeTab === 'record' && (
          <div className="animate-fadeIn flex flex-col gap-6">
            <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100 text-center space-y-6">
              <div className={`w-24 h-24 rounded-full flex items-center justify-center mx-auto transition-all ${isRecording ? 'bg-red-100 animate-pulse' : 'bg-indigo-50'}`}>
                <MicrophoneIcon className={`w-12 h-12 ${isRecording ? 'text-red-600' : 'text-indigo-600'}`} />
              </div>
              <h2 className="text-xl font-bold text-slate-800">영어 발음 연습</h2>
              <div className="flex gap-4 justify-center">
                {!isRecording ? (
                  <button onClick={startRecording} className="bg-indigo-600 text-white font-bold px-8 py-4 rounded-2xl shadow-lg">녹음 시작</button>
                ) : (
                  <button onClick={stopRecording} className="bg-red-600 text-white font-bold px-8 py-4 rounded-2xl shadow-lg">녹음 중지</button>
                )}
              </div>
              {audioUrl && !isRecording && (
                <div className="pt-6 border-t border-slate-100 space-y-4">
                  <div className="flex items-center justify-center gap-4">
                    <button onClick={() => new Audio(audioUrl).play()} className="bg-slate-800 text-white font-bold px-6 py-3 rounded-xl shadow-md"><PlayIcon className="w-5 h-5 inline mr-1" /> 재생</button>
                    <button onClick={() => setAudioUrl(null)} className="text-slate-400 text-xs font-bold underline">삭제</button>
                  </div>
                </div>
              )}
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { WordEntry, DailyRecord, TestResult } from './types';
import { scoreTest } from './services/geminiService';
import { 
  CalendarIcon, 
  PencilSquareIcon, 
  CheckCircleIcon, 
  ArrowPathIcon,
  SpeakerWaveIcon,
  AcademicCapIcon,
  BookOpenIcon,
  SparklesIcon,
  NewspaperIcon,
  MicrophoneIcon,
  StopIcon,
  PlayIcon,
  CloudArrowDownIcon,
  ExclamationCircleIcon
} from '@heroicons/react/24/outline';

const GAS_URL = "https://script.google.com/macros/s/AKfycbyPJsDByc9jma_YM-pPizmJfNt3QpYjDGHoqw89gJCMe0xMGIN5rncRhFvaXaHba79U-A/exec";

const getTodayString = () => {
  const now = new Date();
  const offset = now.getTimezoneOffset() * 60000;
  return new Date(now.getTime() - offset).toISOString().split('T')[0];
};

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'study' | 'test' | 'record'>('study');
  const [testMode, setTestMode] = useState<'none' | 'today' | 'cumulative'>('none');
  const [todayRecord, setTodayRecord] = useState<DailyRecord>({
    date: getTodayString(),
    page: '',
    words: Array(13).fill({ word: '', meaning: '' }),
    newsContent: '',
    isCompleted: false,
  });
  const [history, setHistory] = useState<DailyRecord[]>([]);
  const [sheetWords, setSheetWords] = useState<WordEntry[]>([]);
  const [isLoadingSheet, setIsLoadingSheet] = useState(false);
  const [loadError, setLoadError] = useState<string | null>(null);

  const [testWords, setTestWords] = useState<WordEntry[]>([]);
  const [testStep, setTestStep] = useState(0);
  const [testResults, setTestResults] = useState<TestResult[]>([]);
  const [currentTestInput, setCurrentTestInput] = useState({ spelling: '', meaning: '' });
  const [isScoring, setIsScoring] = useState(false);

  // Recording states
  const [isRecording, setIsRecording] = useState(false);
  const [audioUrl, setAudioUrl] = useState<string | null>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);

  const calendarData = useMemo(() => {
    const now = new Date();
    const year = now.getFullYear();
    const month = now.getMonth();
    const firstDay = new Date(year, month, 1).getDay();
    const lastDate = new Date(year, month + 1, 0).getDate();
    const days = [];
    for (let i = 0; i < firstDay; i++) days.push(null);
    for (let i = 1; i <= lastDate; i++) {
      days.push({
        day: i,
        dateStr: `${year}-${String(month + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`
      });
    }
    return { days, month: month + 1, year };
  }, []);

  // 구글 시트 데이터 로드 (GET)
  const fetchSheetData = async () => {
    setIsLoadingSheet(true);
    setLoadError(null);
    try {
      // 캐시 방지를 위해 타임스탬프 추가
      const url = `${GAS_URL}?t=${Date.now()}`;
      const response = await fetch(url, {
        method: 'GET',
        headers: { 'Accept': 'application/json' }
      });

      if (!response.ok) throw new Error('네트워크 응답에 문제가 있습니다.');

      const text = await response.text();
      let data;
      try {
        data = JSON.parse(text);
      } catch (e) {
        throw new Error('시트 응답 형식이 올바르지 않습니다. (JSON 파싱 에러)');
      }

      if (Array.isArray(data)) {
        const words: WordEntry[] = data
          .filter((item: any) => {
            const w = item.word || item.영어단어;
            return w && String(w).trim() !== "" && String(w).trim() !== "영어단어";
          })
          .map((item: any) => ({
            word: String(item.word || item.영어단어).trim(),
            meaning: String(item.meaning || item.의미).trim()
          }));
        setSheetWords(words);
      }
    } catch (error: any) {
      console.error("Fetch Error:", error);
      setLoadError("데이터를 가져올 수 없습니다. GAS 배포 설정을 확인해주세요.");
    } finally {
      setIsLoadingSheet(false);
    }
  };

  useEffect(() => {
    fetchSheetData();
    const saved = localStorage.getItem('study_history');
    if (saved) {
      const parsed: DailyRecord[] = JSON.parse(saved);
      setHistory(parsed);
      loadRecordForDate(todayRecord.date, parsed);
    }
  }, []);

  const loadRecordForDate = (dateStr: string, currentHistory: DailyRecord[]) => {
    const existing = currentHistory.find(r => r.date === dateStr);
    if (existing) {
      setTodayRecord(existing);
    } else {
      setTodayRecord({
        date: dateStr,
        page: '',
        words: Array(13).fill({ word: '', meaning: '' }),
        newsContent: '',
        isCompleted: false,
      });
    }
  };

  const handleDateChange = (newDate: string) => {
    loadRecordForDate(newDate, history);
  };

  const handleWordChange = (index: number, field: keyof WordEntry, value: string) => {
    const newWords = [...todayRecord.words];
    newWords[index] = { ...newWords[index], [field]: value };
    setTodayRecord({ ...todayRecord, words: newWords });
  };

  const submitStudy = async () => {
    const updatedRecord = { ...todayRecord, isCompleted: true };
    setTodayRecord(updatedRecord);
    const newHistory = [...history.filter(r => r.date !== todayRecord.date), updatedRecord];
    setHistory(newHistory);
    localStorage.setItem('study_history', JSON.stringify(newHistory));

    try {
      await fetch(GAS_URL, {
        method: "POST",
        mode: "no-cors", 
        headers: { "Content-Type": "text/plain" },
        body: JSON.stringify(updatedRecord),
      });
      alert('학습 내용이 시트로 전송되었습니다!');
      setTimeout(fetchSheetData, 1000); // 전송 후 시트 데이터 갱신
    } catch (error) {
      alert('시트 전송 중 오류가 발생했습니다.');
    }
  };

  const startTest = async (mode: 'today' | 'cumulative') => {
    let sourceWords: WordEntry[] = [];

    if (mode === 'today') {
      sourceWords = todayRecord.words.filter(w => w && w.word?.trim() !== "" && w.meaning?.trim() !== "");
      if (sourceWords.length === 0) {
        alert('오늘 입력한 단어가 없습니다!');
        return;
      }
    } else {
      // 누적 테스트 전 데이터가 없으면 다시 시도
      if (sheetWords.length === 0) {
        setIsLoadingSheet(true);
        await fetchSheetData();
      }

      // 시트 데이터에서 중복 제거 및 유효성 검사
      const uniqueMap = new Map();
      sheetWords.forEach(w => {
        if (w.word) uniqueMap.set(w.word.toLowerCase().trim(), w);
      });

      sourceWords = Array.from(uniqueMap.values());

      if (sourceWords.length === 0) {
        alert('시트에 저장된 단어가 없습니다. 먼저 학습을 완료하고 제출해주세요.');
        return;
      }
    }

    const shuffled = [...sourceWords].sort(() => 0.5 - Math.random());
    const finalWords = mode === 'today' ? shuffled : shuffled.slice(0, Math.min(5, shuffled.length));

    setTestWords(finalWords);
    setTestStep(0);
    setTestResults([]);
    setCurrentTestInput({ spelling: '', meaning: '' });
    setTestMode(mode);
    setActiveTab('test');
  };

  const speakWord = (word: string) => {
    const utterance = new SpeechSynthesisUtterance(word);
    utterance.lang = 'en-US';
    window.speechSynthesis.speak(utterance);
  };

  const handleNextTest = async () => {
    if (isScoring) return;
    setIsScoring(true);
    const target = testWords[testStep];
    const score = await scoreTest(target.word, target.meaning, currentTestInput.spelling, currentTestInput.meaning);

    const result: TestResult = {
      word: target.word,
      userSpelling: currentTestInput.spelling,
      userMeaning: currentTestInput.meaning,
      isCorrect: score.isCorrect,
      feedback: score.feedback
    };

    setTestResults([...testResults, result]);
    setIsScoring(false);

    if (testStep < testWords.length - 1) {
      setTestStep(testStep + 1);
      setCurrentTestInput({ spelling: '', meaning: '' });
    }
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];
      mediaRecorder.ondataavailable = (e) => { if (e.data.size > 0) audioChunksRef.current.push(e.data); };
      mediaRecorder.onstop = () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/wav' });
        setAudioUrl(URL.createObjectURL(audioBlob));
      };
      mediaRecorder.start();
      setIsRecording(true);
    } catch (err) { alert("마이크 권한이 필요합니다."); }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      mediaRecorderRef.current.stream.getTracks().forEach(track => track.stop());
    }
  };

  return (
    <div className="min-h-screen pb-24 max-w-2xl mx-auto p-4 flex flex-col gap-6">
      <header className="flex flex-col gap-1 items-center py-6 bg-white rounded-3xl shadow-sm border border-slate-100 relative">
        <div className="absolute top-4 right-4 flex items-center gap-2">
            <div className={`flex items-center gap-1 text-[10px] font-bold px-2 py-1 rounded-full ${loadError ? 'bg-red-50 text-red-500' : 'bg-green-50 text-green-600'}`}>
                {loadError ? <ExclamationCircleIcon className="w-3 h-3" /> : <div className="w-1.5 h-1.5 bg-green-500 rounded-full" />}
                {loadError ? '연결 오류' : `${sheetWords.length}개 누적됨`}
            </div>
            <button onClick={fetchSheetData} className={`p-1.5 rounded-full hover:bg-slate-100 transition-all ${isLoadingSheet ? 'animate-spin' : ''}`}>
                <CloudArrowDownIcon className="w-5 h-5 text-indigo-400" />
            </button>
        </div>
        <h1 className="text-2xl font-bold text-indigo-600 flex items-center gap-2">
          <AcademicCapIcon className="w-8 h-8" />
          영어 학습 기록장
        </h1>
        <p className="text-slate-500 text-sm italic">Cloud Sync Vocab Master</p>
      </header>

      <nav className="flex bg-white p-1 rounded-2xl shadow-sm border border-slate-100 sticky top-4 z-50">
        <button onClick={() => { setActiveTab('study'); setTestMode('none'); }} className={`flex-1 flex flex-col items-center py-3 rounded-xl transition-all ${activeTab === 'study' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}>
          <PencilSquareIcon className="w-6 h-6" />
          <span className="text-[10px] mt-1 font-bold">학습/수정</span>
        </button>
        <button onClick={() => { setActiveTab('test'); setTestMode('none'); }} className={`flex-1 flex flex-col items-center py-3 rounded-xl transition-all ${activeTab === 'test' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}>
          <ArrowPathIcon className="w-6 h-6" />
          <span className="text-[10px] mt-1 font-bold">테스트</span>
        </button>
        <button onClick={() => { setActiveTab('record'); setTestMode('none'); }} className={`flex-1 flex flex-col items-center py-3 rounded-xl transition-all ${activeTab === 'record' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}>
          <MicrophoneIcon className="w-6 h-6" />
          <span className="text-[10px] mt-1 font-bold">발음 연습</span>
        </button>
      </nav>

      <main className="flex-1">
        {activeTab === 'study' && (
          <div className="flex flex-col gap-6 animate-fadeIn">
            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 space-y-4">
               <div className="flex justify-between items-center">
                 <h2 className="text-lg font-bold text-slate-800">학습 정보</h2>
                 <span className={`px-4 py-1 rounded-full text-[11px] font-bold ${todayRecord.isCompleted ? 'bg-green-100 text-green-700' : 'bg-amber-100 text-amber-700'}`}>
                    {todayRecord.isCompleted ? '학습완료' : '기록중'}
                 </span>
               </div>
               <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">날짜 선택</label>
                    <input type="date" value={todayRecord.date} onChange={(e) => handleDateChange(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-1 text-sm font-bold text-slate-700 outline-none" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">페이지</label>
                    <input type="text" placeholder="예: 10-15" disabled={todayRecord.isCompleted} value={todayRecord.page} onChange={(e) => setTodayRecord({...todayRecord, page: e.target.value})} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-1 text-sm outline-none" />
                  </div>
               </div>
            </div>

            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 space-y-3">
              <h3 className="font-bold text-slate-700 flex items-center gap-2"><NewspaperIcon className="w-5 h-5 text-indigo-500" />영자신문 요약</h3>
              <textarea placeholder="오늘 읽은 기사의 내용을 적어주세요..." disabled={todayRecord.isCompleted} value={todayRecord.newsContent} onChange={(e) => setTodayRecord({...todayRecord, newsContent: e.target.value})} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm min-h-[100px] outline-none" />
            </div>

            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 space-y-3">
              <h3 className="font-bold text-slate-700">단어 입력 (13개)</h3>
              <div className="grid grid-cols-1 gap-2">
                {todayRecord.words.map((w, idx) => (
                  <div key={idx} className="flex gap-2 items-center">
                    <span className="w-5 text-[10px] font-bold text-slate-300">{idx + 1}</span>
                    <input type="text" placeholder="Word" disabled={todayRecord.isCompleted} value={w.word} onChange={(e) => handleWordChange(idx, 'word', e.target.value)} className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-indigo-500" />
                    <input type="text" placeholder="뜻" disabled={todayRecord.isCompleted} value={w.meaning} onChange={(e) => handleWordChange(idx, 'meaning', e.target.value)} className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-indigo-500" />
                  </div>
                ))}
              </div>
              <div className="pt-4">
                {todayRecord.isCompleted ? (
                  <button onClick={() => setTodayRecord({...todayRecord, isCompleted: false})} className="w-full bg-slate-100 text-slate-600 font-bold py-4 rounded-2xl flex items-center justify-center gap-2">
                    <PencilSquareIcon className="w-5 h-5" /> 수정하기
                  </button>
                ) : (
                  <button onClick={submitStudy} className="w-full bg-indigo-600 text-white font-bold py-4 rounded-2xl shadow-lg flex items-center justify-center gap-2">
                    <CheckCircleIcon className="w-5 h-5" /> 학습완료 제출 (시트 저장)
                  </button>
                )}
              </div>
            </div>

            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
              <h2 className="text-lg font-bold mb-6 text-slate-800 flex items-center gap-2"><CalendarIcon className="w-6 h-6 text-indigo-500" />학습 달력</h2>
              <div className="grid grid-cols-7 gap-2 text-center">
                {['일','월','화','수','목','금','토'].map(d => (<div key={d} className="text-[10px] font-bold text-slate-400 py-2 uppercase">{d}</div>))}
                {calendarData.days.map((dayObj, i) => {
                  if (!dayObj) return <div key={`empty-${i}`} />;
                  const record = history.find(r => r.date === dayObj.dateStr);
                  const isFinished = record && record.isCompleted;
                  const isSelected = dayObj.dateStr === todayRecord.date;
                  return (
                    <button key={i} onClick={() => handleDateChange(dayObj.dateStr)} className={`aspect-square flex flex-col items-center justify-center rounded-2xl border transition-all ${isFinished ? 'bg-green-50 border-green-200' : isSelected ? 'bg-indigo-600 border-indigo-600 text-white shadow-md' : 'bg-slate-50 border-slate-100 hover:bg-slate-100'}`}>
                      <span className={`text-[11px] font-bold ${isSelected ? 'text-white' : isFinished ? 'text-green-700' : 'text-slate-500'}`}>{dayObj.day}</span>
                      {isFinished && !isSelected && <div className="text-[7px] font-bold text-green-500 mt-0.5">완료</div>}
                    </button>
                  );
                })}
              </div>
            </div>
          </div>
        )}

        {activeTab === 'test' && (
          <div className="animate-fadeIn">
            {testMode === 'none' ? (
              <div className="grid grid-cols-1 gap-6">
                {loadError && (
                  <div className="bg-red-50 border border-red-100 p-4 rounded-2xl flex items-start gap-3">
                    <ExclamationCircleIcon className="w-5 h-5 text-red-500 shrink-0 mt-0.5" />
                    <div>
                      <p className="text-sm font-bold text-red-800">시트 연결 오류</p>
                      <p className="text-xs text-red-600 leading-relaxed mt-1">구글 시트에서 단어를 불러오지 못했습니다. 앱스 스크립트 배포 시 '액세스 권한'을 '모든 사용자'로 설정했는지 확인해주세요.</p>
                    </div>
                  </div>
                )}

                <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100 text-center space-y-4">
                  <BookOpenIcon className="w-10 h-10 text-indigo-600 mx-auto" />
                  <h2 className="text-xl font-bold text-slate-800">오늘의 단어 테스트</h2>
                  <p className="text-slate-500 text-sm">{todayRecord.date}에 기록 중인 단어들로 시험을 봅니다.</p>
                  <button onClick={() => startTest('today')} className="w-full bg-indigo-600 text-white font-bold py-4 rounded-2xl shadow-lg hover:bg-indigo-700 transition-all">오늘 시험 시작</button>
                </div>

                <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100 text-center space-y-4">
                  <SparklesIcon className="w-10 h-10 text-violet-600 mx-auto" />
                  <h2 className="text-xl font-bold text-slate-800">누가기록 전체 테스트</h2>
                  <p className="text-slate-500 text-sm">구글 시트에 지금까지 저장된 모든 단어 중 5개를 랜덤 출제합니다.<br/>({sheetWords.length}개 단어 대기 중)</p>
                  <button 
                    onClick={() => startTest('cumulative')} 
                    className={`w-full font-bold py-4 rounded-2xl shadow-lg transition-all ${sheetWords.length > 0 ? 'bg-violet-600 text-white hover:bg-violet-700' : 'bg-slate-100 text-slate-400 cursor-not-allowed'}`}
                  >
                    전체 랜덤 시험 시작
                  </button>
                </div>
              </div>
            ) : (
              <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100 min-h-[500px] flex flex-col justify-center text-center relative overflow-hidden">
                {testResults.length === testWords.length ? (
                  <div className="space-y-6">
                    <h2 className="text-2xl font-bold text-slate-800">테스트 결과</h2>
                    <div className="text-lg text-slate-600">정답: <span className="font-bold text-indigo-600">{testResults.filter(r => r.isCorrect).length}</span> / {testWords.length}</div>
                    <div className="space-y-2 text-left overflow-y-auto max-h-[300px] pr-2 custom-scrollbar">
                      {testResults.map((r, i) => (
                        <div key={i} className={`p-4 rounded-2xl border ${r.isCorrect ? 'bg-green-50' : 'bg-red-50'}`}>
                          <div className="flex justify-between font-bold text-sm"><span>{r.word}</span><span>{r.isCorrect ? '⭕' : '❌'}</span></div>
                          <p className="text-xs text-slate-500 mt-1">{r.feedback}</p>
                        </div>
                      ))}
                    </div>
                    <button onClick={() => setTestMode('none')} className="w-full bg-slate-800 text-white font-bold py-4 rounded-2xl shadow-md">돌아가기</button>
                  </div>
                ) : (
                  <div className="space-y-8">
                    <div className="absolute top-0 left-0 w-full h-1.5 bg-slate-100">
                      <div className="h-full bg-indigo-500 transition-all duration-300" style={{ width: `${((testStep + 1) / testWords.length) * 100}%` }} />
                    </div>
                    <div>
                      <div className="text-xs font-bold text-slate-300 mb-6 uppercase tracking-widest">Question {testStep + 1} / {testWords.length}</div>
                      <button onClick={() => speakWord(testWords[testStep].word)} className="w-24 h-24 bg-indigo-50 rounded-full flex items-center justify-center mx-auto hover:bg-indigo-100 active:scale-95 group">
                        <SpeakerWaveIcon className="w-10 h-10 text-indigo-600 group-hover:scale-110 transition-transform" />
                      </button>
                    </div>
                    <div className="space-y-4 max-w-sm mx-auto">
                      <input type="text" placeholder="Spelling" value={currentTestInput.spelling} onChange={(e) => setCurrentTestInput({...currentTestInput, spelling: e.target.value})} className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-6 py-4 text-center text-xl font-bold outline-none focus:ring-2 focus:ring-indigo-500" />
                      <input type="text" placeholder="뜻" value={currentTestInput.meaning} onChange={(e) => setCurrentTestInput({...currentTestInput, meaning: e.target.value})} className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-6 py-4 text-center text-xl font-bold outline-none focus:ring-2 focus:ring-indigo-500" />
                    </div>
                    <button onClick={handleNextTest} disabled={isScoring || !currentTestInput.spelling.trim() || !currentTestInput.meaning.trim()} className="w-full max-w-sm mx-auto bg-indigo-600 text-white font-bold py-4 rounded-2xl shadow-lg flex items-center justify-center gap-2">
                      {isScoring ? 'AI 채점 중...' : '다음 문제'}
                    </button>
                  </div>
                )}
              </div>
            )}
          </div>
        )}

        {activeTab === 'record' && (
          <div className="animate-fadeIn flex flex-col gap-6">
            <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100 text-center space-y-6">
              <div className={`w-24 h-24 rounded-full flex items-center justify-center mx-auto transition-all ${isRecording ? 'bg-red-100 animate-pulse' : 'bg-indigo-50'}`}>
                <MicrophoneIcon className={`w-12 h-12 ${isRecording ? 'text-red-600' : 'text-indigo-600'}`} />
              </div>
              <h2 className="text-xl font-bold text-slate-800">영어 발음 연습</h2>
              <div className="flex gap-4 justify-center">
                {!isRecording ? (
                  <button onClick={startRecording} className="bg-indigo-600 text-white font-bold px-8 py-4 rounded-2xl shadow-lg hover:bg-indigo-700 transition-all">녹음 시작</button>
                ) : (
                  <button onClick={stopRecording} className="bg-red-600 text-white font-bold px-8 py-4 rounded-2xl shadow-lg hover:bg-red-700 transition-all">녹음 중지</button>
                )}
              </div>
              {audioUrl && !isRecording && (
                <div className="pt-6 border-t border-slate-100 space-y-4">
                  <div className="flex items-center justify-center gap-4">
                    <button onClick={() => new Audio(audioUrl).play()} className="bg-slate-800 text-white font-bold px-6 py-3 rounded-xl shadow-md flex items-center gap-2 hover:bg-slate-900 transition-all"><PlayIcon className="w-5 h-5" /> 재생</button>
                    <button onClick={() => setAudioUrl(null)} className="text-slate-400 text-xs font-bold underline hover:text-red-500">삭제</button>
                  </div>
                </div>
              )}
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const scoreTest = async (
  originalWord: string,
  originalMeaning: string,
  userSpelling: string,
  userMeaning: string
) => {
  const prompt = `
    당신은 중학생의 영어 단어 테스트를 채점하는 친절한 AI 선생님입니다.

    [채점 기준]
    1. 영어 스펠링: 대소문자 구분 없이 글자가 정확히 일치해야 합니다. (완벽 일치 필수)
    2. 의미(뜻): 입력된 뜻이 원래의 뜻과 유의어이거나 문맥상 같은 의미라면 정답으로 처리합니다.
       - 예: 원래 뜻이 '뛰다'인데 학생이 '달리다'라고 적으면 정답(isCorrect: true)입니다.
       - 예: 원래 뜻이 '행복한'인데 학생이 '기쁜'이라고 적으면 정답입니다.
       - 예: 원래 뜻과 전혀 상관없는 뜻이면 오답입니다.

    [대상 데이터]
    - 목표 단어: "${originalWord}"
    - 목표 의미: "${originalMeaning}"
    - 학생이 쓴 스펠링: "${userSpelling}"
    - 학생이 쓴 의미: "${userMeaning}"

    결과는 반드시 아래의 JSON 형식으로만 답변하세요.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            isCorrect: { type: Type.BOOLEAN },
            feedback: { type: Type.STRING, description: "정답 여부에 따른 짧고 격려 섞인 한국어 피드백 (예: '의미가 아주 잘 통하네요! 정답입니다.')" }
          },
          required: ["isCorrect", "feedback"]
        }
      }
    });

    return JSON.parse(response.text);
  } catch (error) {
    console.error("AI Scoring Error:", error);
    const spellingMatch = originalWord.toLowerCase().trim() === userSpelling.toLowerCase().trim();
    const meaningMatch = originalMeaning.trim() === userMeaning.trim();
    return {
      isCorrect: spellingMatch && meaningMatch,
      feedback: spellingMatch && meaningMatch ? "완벽합니다!" : `아쉬워요. 정답은 ${originalWord}: ${originalMeaning} 입니다.`
    };
  }
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { WordEntry, DailyRecord, TestResult } from './types';
import { scoreTest } from './services/geminiService';
import { 
  CalendarIcon, 
  PencilSquareIcon, 
  CheckCircleIcon, 
  ArrowPathIcon,
  SpeakerWaveIcon,
  AcademicCapIcon,
  BookOpenIcon,
  SparklesIcon,
  NewspaperIcon,
  MicrophoneIcon,
  StopIcon,
  PlayIcon,
  CloudArrowDownIcon,
  ExclamationCircleIcon
} from '@heroicons/react/24/outline';

const GAS_URL = "https://script.google.com/macros/s/AKfycbyPJsDByc9jma_YM-pPizmJfNt3QpYjDGHoqw89gJCMe0xMGIN5rncRhFvaXaHba79U-A/exec";

const getTodayString = () => {
  const now = new Date();
  const offset = now.getTimezoneOffset() * 60000;
  return new Date(now.getTime() - offset).toISOString().split('T')[0];
};

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'study' | 'test' | 'record'>('study');
  const [testMode, setTestMode] = useState<'none' | 'today' | 'cumulative'>('none');
  const [todayRecord, setTodayRecord] = useState<DailyRecord>({
    date: getTodayString(),
    page: '',
    words: Array(13).fill({ word: '', meaning: '' }),
    newsContent: '',
    isCompleted: false,
  });
  const [history, setHistory] = useState<DailyRecord[]>([]);
  const [sheetWords, setSheetWords] = useState<WordEntry[]>([]);
  const [isLoadingSheet, setIsLoadingSheet] = useState(false);
  const [loadError, setLoadError] = useState<string | null>(null);

  const [testWords, setTestWords] = useState<WordEntry[]>([]);
  const [testStep, setTestStep] = useState(0);
  const [testResults, setTestResults] = useState<TestResult[]>([]);
  const [currentTestInput, setCurrentTestInput] = useState({ spelling: '', meaning: '' });
  const [isScoring, setIsScoring] = useState(false);

  // Recording states
  const [isRecording, setIsRecording] = useState(false);
  const [audioUrl, setAudioUrl] = useState<string | null>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);

  const calendarData = useMemo(() => {
    const now = new Date();
    const year = now.getFullYear();
    const month = now.getMonth();
    const firstDay = new Date(year, month, 1).getDay();
    const lastDate = new Date(year, month + 1, 0).getDate();
    const days = [];
    for (let i = 0; i < firstDay; i++) days.push(null);
    for (let i = 1; i <= lastDate; i++) {
      days.push({
        day: i,
        dateStr: `${year}-${String(month + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`
      });
    }
    return { days, month: month + 1, year };
  }, []);

  // 구글 시트 데이터 로드 (GET)
  const fetchSheetData = async () => {
    setIsLoadingSheet(true);
    setLoadError(null);
    try {
      // GAS Web App은 커스텀 헤더가 있으면 CORS 에러를 발생시킬 수 있으므로 
      // headers를 제거하고 단순한 GET 요청으로 처리합니다.
      const url = `${GAS_URL}?t=${Date.now()}`;
      const response = await fetch(url);

      if (!response.ok) throw new Error(`서버 응답 오류: ${response.status}`);

      const data = await response.json();

      if (Array.isArray(data)) {
        const words: WordEntry[] = data
          .filter((item: any) => {
            const w = item.word || item.영어단어 || item.English;
            const skipWords = ["영어단어", "word", "english"];
            return w && String(w).trim() !== "" && !skipWords.includes(String(w).toLowerCase().trim());
          })
          .map((item: any) => ({
            word: String(item.word || item.영어단어 || item.English).trim(),
            meaning: String(item.meaning || item.의미 || item.Meaning).trim()
          }));

        // 중복 제거 (대소문자 무시)
        const uniqueWordsMap = new Map();
        words.forEach(w => uniqueWordsMap.set(w.word.toLowerCase(), w));

        const finalWords = Array.from(uniqueWordsMap.values());
        setSheetWords(finalWords);
        console.log(`Loaded ${finalWords.length} unique words from sheet.`);
      }
    } catch (error: any) {
      console.error("Fetch Error:", error);
      setLoadError("시트 데이터를 불러오지 못했습니다. GAS 배포 권한 설정을 확인해주세요.");
    } finally {
      setIsLoadingSheet(false);
    }
  };

  useEffect(() => {
    fetchSheetData();
    const saved = localStorage.getItem('study_history');
    if (saved) {
      const parsed: DailyRecord[] = JSON.parse(saved);
      setHistory(parsed);
      loadRecordForDate(todayRecord.date, parsed);
    }
  }, []);

  const loadRecordForDate = (dateStr: string, currentHistory: DailyRecord[]) => {
    const existing = currentHistory.find(r => r.date === dateStr);
    if (existing) {
      setTodayRecord(existing);
    } else {
      setTodayRecord({
        date: dateStr,
        page: '',
        words: Array(13).fill({ word: '', meaning: '' }),
        newsContent: '',
        isCompleted: false,
      });
    }
  };

  const handleDateChange = (newDate: string) => {
    loadRecordForDate(newDate, history);
  };

  const handleWordChange = (index: number, field: keyof WordEntry, value: string) => {
    const newWords = [...todayRecord.words];
    newWords[index] = { ...newWords[index], [field]: value };
    setTodayRecord({ ...todayRecord, words: newWords });
  };

  const submitStudy = async () => {
    const updatedRecord = { ...todayRecord, isCompleted: true };
    setTodayRecord(updatedRecord);
    const newHistory = [...history.filter(r => r.date !== todayRecord.date), updatedRecord];
    setHistory(newHistory);
    localStorage.setItem('study_history', JSON.stringify(newHistory));

    try {
      await fetch(GAS_URL, {
        method: "POST",
        mode: "no-cors", 
        headers: { "Content-Type": "text/plain" },
        body: JSON.stringify(updatedRecord),
      });
      alert('학습 내용이 시트로 전송되었습니다!');
      // 전송 성공 후 약간의 딜레이를 두고 다시 불러와 동기화 시도
      setTimeout(fetchSheetData, 1500);
    } catch (error) {
      alert('시트 전송 중 오류가 발생했습니다.');
    }
  };

  const startTest = async (mode: 'today' | 'cumulative') => {
    let sourceWords: WordEntry[] = [];

    if (mode === 'today') {
      sourceWords = todayRecord.words.filter(w => w && w.word?.trim() !== "" && w.meaning?.trim() !== "");
      if (sourceWords.length === 0) {
        alert('오늘 입력한 단어가 없습니다!');
        return;
      }
    } else {
      // 시트 데이터가 없는 경우를 위한 폴백: 로컬 히스토리에서도 추출
      const historyWords = history.flatMap(h => h.words || []).filter(w => w.word && w.word.trim() !== "");

      const combined = [...sheetWords, ...historyWords];
      const uniqueMap = new Map();
      combined.forEach(w => uniqueMap.set(w.word.toLowerCase().trim(), w));

      sourceWords = Array.from(uniqueMap.values());

      if (sourceWords.length === 0) {
        alert('테스트할 저장된 단어가 없습니다. 학습을 완료하고 제출해주세요.');
        return;
      }
    }

    const shuffled = [...sourceWords].sort(() => 0.5 - Math.random());
    const finalWords = mode === 'today' ? shuffled : shuffled.slice(0, Math.min(5, shuffled.length));

    setTestWords(finalWords);
    setTestStep(0);
    setTestResults([]);
    setCurrentTestInput({ spelling: '', meaning: '' });
    setTestMode(mode);
    setActiveTab('test');
  };

  const speakWord = (word: string) => {
    const utterance = new SpeechSynthesisUtterance(word);
    utterance.lang = 'en-US';
    window.speechSynthesis.speak(utterance);
  };

  const handleNextTest = async () => {
    if (isScoring) return;
    setIsScoring(true);
    const target = testWords[testStep];
    const score = await scoreTest(target.word, target.meaning, currentTestInput.spelling, currentTestInput.meaning);

    const result: TestResult = {
      word: target.word,
      userSpelling: currentTestInput.spelling,
      userMeaning: currentTestInput.meaning,
      isCorrect: score.isCorrect,
      feedback: score.feedback
    };

    setTestResults([...testResults, result]);
    setIsScoring(false);

    if (testStep < testWords.length - 1) {
      setTestStep(testStep + 1);
      setCurrentTestInput({ spelling: '', meaning: '' });
    }
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];
      mediaRecorder.ondataavailable = (e) => { if (e.data.size > 0) audioChunksRef.current.push(e.data); };
      mediaRecorder.onstop = () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/wav' });
        setAudioUrl(URL.createObjectURL(audioBlob));
      };
      mediaRecorder.start();
      setIsRecording(true);
    } catch (err) { alert("마이크 권한이 필요합니다."); }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      mediaRecorderRef.current.stream.getTracks().forEach(track => track.stop());
    }
  };

  return (
    <div className="min-h-screen pb-24 max-w-2xl mx-auto p-4 flex flex-col gap-6">
      <header className="flex flex-col gap-1 items-center py-6 bg-white rounded-3xl shadow-sm border border-slate-100 relative">
        <div className="absolute top-4 right-4 flex items-center gap-2">
            <div className={`flex items-center gap-1 text-[10px] font-bold px-2 py-1 rounded-full ${loadError ? 'bg-red-50 text-red-500' : 'bg-indigo-50 text-indigo-600'}`}>
                {loadError ? <ExclamationCircleIcon className="w-3 h-3" /> : <div className="w-1.5 h-1.5 bg-indigo-500 rounded-full animate-pulse" />}
                {loadError ? '연결 오류' : `${sheetWords.length}개 동기화됨`}
            </div>
            <button onClick={fetchSheetData} className={`p-1.5 rounded-full hover:bg-slate-100 transition-all ${isLoadingSheet ? 'animate-spin' : ''}`}>
                <CloudArrowDownIcon className="w-5 h-5 text-indigo-400" />
            </button>
        </div>
        <h1 className="text-2xl font-bold text-indigo-600 flex items-center gap-2">
          <AcademicCapIcon className="w-8 h-8" />
          영어 학습 기록장
        </h1>
        <p className="text-slate-500 text-sm italic">Cloud Vocabulary Sync</p>
      </header>

      <nav className="flex bg-white p-1 rounded-2xl shadow-sm border border-slate-100 sticky top-4 z-50">
        <button onClick={() => { setActiveTab('study'); setTestMode('none'); }} className={`flex-1 flex flex-col items-center py-3 rounded-xl transition-all ${activeTab === 'study' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}>
          <PencilSquareIcon className="w-6 h-6" />
          <span className="text-[10px] mt-1 font-bold uppercase tracking-wide">학습기록</span>
        </button>
        <button onClick={() => { setActiveTab('test'); setTestMode('none'); }} className={`flex-1 flex flex-col items-center py-3 rounded-xl transition-all ${activeTab === 'test' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}>
          <ArrowPathIcon className="w-6 h-6" />
          <span className="text-[10px] mt-1 font-bold uppercase tracking-wide">테스트</span>
        </button>
        <button onClick={() => { setActiveTab('record'); setTestMode('none'); }} className={`flex-1 flex flex-col items-center py-3 rounded-xl transition-all ${activeTab === 'record' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}>
          <MicrophoneIcon className="w-6 h-6" />
          <span className="text-[10px] mt-1 font-bold uppercase tracking-wide">발음연습</span>
        </button>
      </nav>

      <main className="flex-1">
        {activeTab === 'study' && (
          <div className="flex flex-col gap-6 animate-fadeIn">
            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 space-y-4">
               <div className="flex justify-between items-center">
                 <h2 className="text-lg font-bold text-slate-800">기록 정보</h2>
                 <span className={`px-4 py-1 rounded-full text-[11px] font-bold ${todayRecord.isCompleted ? 'bg-green-100 text-green-700' : 'bg-amber-100 text-amber-700'}`}>
                    {todayRecord.isCompleted ? '학습완료' : '작성중'}
                 </span>
               </div>
               <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">학습 날짜</label>
                    <input type="date" value={todayRecord.date} onChange={(e) => handleDateChange(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-1 text-sm font-bold text-slate-700 outline-none focus:ring-2 focus:ring-indigo-500" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">범위 (페이지)</label>
                    <input type="text" placeholder="예: 10-15" disabled={todayRecord.isCompleted} value={todayRecord.page} onChange={(e) => setTodayRecord({...todayRecord, page: e.target.value})} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-1 text-sm outline-none focus:ring-2 focus:ring-indigo-500" />
                  </div>
               </div>
            </div>

            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 space-y-3">
              <h3 className="font-bold text-slate-700 flex items-center gap-2"><NewspaperIcon className="w-5 h-5 text-indigo-500" />영자신문 읽기</h3>
              <textarea placeholder="오늘 읽은 뉴스 기사의 주요 단어나 소감을 기록하세요..." disabled={todayRecord.isCompleted} value={todayRecord.newsContent} onChange={(e) => setTodayRecord({...todayRecord, newsContent: e.target.value})} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm min-h-[100px] outline-none" />
            </div>

            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 space-y-3">
              <h3 className="font-bold text-slate-700">단어 기록 (13개)</h3>
              <div className="grid grid-cols-1 gap-2">
                {todayRecord.words.map((w, idx) => (
                  <div key={idx} className="flex gap-2 items-center">
                    <span className="w-5 text-[10px] font-bold text-slate-300">{idx + 1}</span>
                    <input type="text" placeholder="Word" disabled={todayRecord.isCompleted} value={w.word} onChange={(e) => handleWordChange(idx, 'word', e.target.value)} className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-indigo-500" />
                    <input type="text" placeholder="뜻" disabled={todayRecord.isCompleted} value={w.meaning} onChange={(e) => handleWordChange(idx, 'meaning', e.target.value)} className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-indigo-500" />
                  </div>
                ))}
              </div>
              <div className="pt-4">
                {todayRecord.isCompleted ? (
                  <button onClick={() => setTodayRecord({...todayRecord, isCompleted: false})} className="w-full bg-slate-100 text-slate-600 font-bold py-4 rounded-2xl flex items-center justify-center gap-2 hover:bg-slate-200 transition-all">
                    <PencilSquareIcon className="w-5 h-5" /> 수정하기
                  </button>
                ) : (
                  <button onClick={submitStudy} className="w-full bg-indigo-600 text-white font-bold py-4 rounded-2xl shadow-lg flex items-center justify-center gap-2 hover:bg-indigo-700 transition-all">
                    <CheckCircleIcon className="w-5 h-5" /> 학습완료 및 저장
                  </button>
                )}
              </div>
            </div>

            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
              <h2 className="text-lg font-bold mb-6 text-slate-800 flex items-center gap-2"><CalendarIcon className="w-6 h-6 text-indigo-500" />학습 진행도</h2>
              <div className="grid grid-cols-7 gap-2 text-center">
                {['일','월','화','수','목','금','토'].map(d => (<div key={d} className="text-[10px] font-bold text-slate-400 py-2 uppercase">{d}</div>))}
                {calendarData.days.map((dayObj, i) => {
                  if (!dayObj) return <div key={`empty-${i}`} />;
                  const record = history.find(r => r.date === dayObj.dateStr);
                  const isFinished = record && record.isCompleted;
                  const isSelected = dayObj.dateStr === todayRecord.date;
                  return (
                    <button key={i} onClick={() => handleDateChange(dayObj.dateStr)} className={`aspect-square flex flex-col items-center justify-center rounded-2xl border transition-all ${isFinished ? 'bg-green-50 border-green-200' : isSelected ? 'bg-indigo-600 border-indigo-600 text-white shadow-md' : 'bg-slate-50 border-slate-100 hover:bg-slate-100'}`}>
                      <span className={`text-[11px] font-bold ${isSelected ? 'text-white' : isFinished ? 'text-green-700' : 'text-slate-500'}`}>{dayObj.day}</span>
                      {isFinished && !isSelected && <div className="text-[7px] font-bold text-green-500 mt-0.5">완료</div>}
                    </button>
                  );
                })}
              </div>
            </div>
          </div>
        )}

        {activeTab === 'test' && (
          <div className="animate-fadeIn">
            {testMode === 'none' ? (
              <div className="grid grid-cols-1 gap-6">
                {loadError && (
                  <div className="bg-red-50 border border-red-100 p-4 rounded-2xl flex items-start gap-3">
                    <ExclamationCircleIcon className="w-5 h-5 text-red-500 shrink-0 mt-0.5" />
                    <div>
                      <p className="text-sm font-bold text-red-800">데이터 동기화 이슈</p>
                      <p className="text-xs text-red-600 leading-relaxed mt-1">구글 시트에서 최신 단어를 가져오지 못했습니다. GAS 배포 권한을 "모든 사용자"로 설정했는지 확인해 보세요.</p>
                      <button onClick={fetchSheetData} className="text-xs font-bold text-red-500 underline mt-2">다시 시도하기</button>
                    </div>
                  </div>
                )}

                <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100 text-center space-y-4">
                  <BookOpenIcon className="w-10 h-10 text-indigo-600 mx-auto" />
                  <h2 className="text-xl font-bold text-slate-800">오늘의 단어 테스트</h2>
                  <p className="text-slate-500 text-sm">방금 기록한 단어들로 실력을 점검합니다.</p>
                  <button onClick={() => startTest('today')} className="w-full bg-indigo-600 text-white font-bold py-4 rounded-2xl shadow-lg hover:bg-indigo-700 transition-all">오늘 시험 시작</button>
                </div>

                <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100 text-center space-y-4">
                  <SparklesIcon className="w-10 h-10 text-violet-600 mx-auto" />
                  <h2 className="text-xl font-bold text-slate-800">누가기록 전체 테스트</h2>
                  <p className="text-slate-500 text-sm">구글 시트에 저장된 모든 단어 중<br/>5개를 랜덤하게 출제합니다. ({sheetWords.length}개 로드됨)</p>
                  <button 
                    onClick={() => startTest('cumulative')} 
                    className={`w-full font-bold py-4 rounded-2xl shadow-lg transition-all ${ (sheetWords.length > 0 || history.length > 0) ? 'bg-violet-600 text-white hover:bg-violet-700' : 'bg-slate-100 text-slate-400 cursor-not-allowed'}`}
                  >
                    누적 랜덤 시험 시작
                  </button>
                </div>
              </div>
            ) : (
              <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100 min-h-[500px] flex flex-col justify-center text-center relative overflow-hidden">
                {testResults.length === testWords.length ? (
                  <div className="space-y-6">
                    <h2 className="text-2xl font-bold text-slate-800">테스트 종료!</h2>
                    <div className="text-lg text-slate-600">최종 점수: <span className="font-bold text-indigo-600">{testResults.filter(r => r.isCorrect).length}</span> / {testWords.length}</div>
                    <div className="space-y-2 text-left overflow-y-auto max-h-[300px] pr-2 custom-scrollbar">
                      {testResults.map((r, i) => (
                        <div key={i} className={`p-4 rounded-2xl border transition-all ${r.isCorrect ? 'bg-green-50 border-green-100' : 'bg-red-50 border-red-100'}`}>
                          <div className="flex justify-between font-bold text-sm"><span>{r.word}</span><span>{r.isCorrect ? '⭕ 정답' : '❌ 오답'}</span></div>
                          <p className="text-xs text-slate-500 mt-1">{r.feedback}</p>
                        </div>
                      ))}
                    </div>
                    <button onClick={() => setTestMode('none')} className="w-full bg-slate-800 text-white font-bold py-4 rounded-2xl shadow-md hover:bg-slate-900 transition-all">메뉴로 돌아가기</button>
                  </div>
                ) : (
                  <div className="space-y-8">
                    <div className="absolute top-0 left-0 w-full h-1.5 bg-slate-100">
                      <div className="h-full bg-indigo-500 transition-all duration-300" style={{ width: `${((testStep + 1) / testWords.length) * 100}%` }} />
                    </div>
                    <div>
                      <div className="text-xs font-bold text-slate-300 mb-6 uppercase tracking-widest">Question {testStep + 1} / {testWords.length}</div>
                      <button onClick={() => speakWord(testWords[testStep].word)} className="w-24 h-24 bg-indigo-50 rounded-full flex items-center justify-center mx-auto hover:bg-indigo-100 active:scale-95 group transition-all">
                        <SpeakerWaveIcon className="w-10 h-10 text-indigo-600 group-hover:scale-110 transition-transform" />
                      </button>
                      <p className="text-[10px] text-slate-400 mt-4">단어를 잘 듣고 아래에 적으세요</p>
                    </div>
                    <div className="space-y-4 max-w-sm mx-auto">
                      <input type="text" placeholder="Spelling" value={currentTestInput.spelling} onChange={(e) => setCurrentTestInput({...currentTestInput, spelling: e.target.value})} className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-6 py-4 text-center text-xl font-bold outline-none focus:ring-2 focus:ring-indigo-500 transition-all" />
                      <input type="text" placeholder="뜻 (한글)" value={currentTestInput.meaning} onChange={(e) => setCurrentTestInput({...currentTestInput, meaning: e.target.value})} className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-6 py-4 text-center text-xl font-bold outline-none focus:ring-2 focus:ring-indigo-500 transition-all" />
                    </div>
                    <button onClick={handleNextTest} disabled={isScoring || !currentTestInput.spelling.trim() || !currentTestInput.meaning.trim()} className="w-full max-w-sm mx-auto bg-indigo-600 text-white font-bold py-4 rounded-2xl shadow-lg flex items-center justify-center gap-2 hover:bg-indigo-700 transition-all">
                      {isScoring ? (
                        <>
                          <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                          채점 중...
                        </>
                      ) : '제출하고 다음으로'}
                    </button>
                  </div>
                )}
              </div>
            )}
          </div>
        )}

        {activeTab === 'record' && (
          <div className="animate-fadeIn flex flex-col gap-6">
            <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100 text-center space-y-6">
              <div className={`w-24 h-24 rounded-full flex items-center justify-center mx-auto transition-all ${isRecording ? 'bg-red-100 animate-pulse scale-110' : 'bg-indigo-50'}`}>
                <MicrophoneIcon className={`w-12 h-12 ${isRecording ? 'text-red-600' : 'text-indigo-600'}`} />
              </div>
              <div>
                <h2 className="text-xl font-bold text-slate-800">영어 발음 연습</h2>
                <p className="text-slate-500 text-sm mt-1">오늘 배운 단어를 직접 읽고 녹음하며 발음을 확인해 보세요.</p>
              </div>
              <div className="flex gap-4 justify-center">
                {!isRecording ? (
                  <button onClick={startRecording} className="bg-indigo-600 text-white font-bold px-8 py-4 rounded-2xl shadow-lg hover:bg-indigo-700 transition-all flex items-center gap-2">
                    <MicrophoneIcon className="w-5 h-5" /> 녹음 시작
                  </button>
                ) : (
                  <button onClick={stopRecording} className="bg-red-600 text-white font-bold px-8 py-4 rounded-2xl shadow-lg hover:bg-red-700 transition-all flex items-center gap-2">
                    <StopIcon className="w-5 h-5" /> 녹음 중지
                  </button>
                )}
              </div>
              {audioUrl && !isRecording && (
                <div className="pt-6 border-t border-slate-100 space-y-4">
                  <div className="flex items-center justify-center gap-4">
                    <button onClick={() => new Audio(audioUrl).play()} className="bg-slate-800 text-white font-bold px-6 py-3 rounded-xl shadow-md flex items-center gap-2 hover:bg-slate-900 transition-all"><PlayIcon className="w-5 h-5" /> 내 녹음 듣기</button>
                    <button onClick={() => setAudioUrl(null)} className="text-slate-400 text-xs font-bold underline hover:text-red-500 transition-colors">새로 녹음하기</button>
                  </div>
                </div>
              )}
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { WordEntry, DailyRecord, TestResult } from './types';
import { scoreTest } from './services/geminiService';
import { 
  CalendarIcon, 
  PencilSquareIcon, 
  CheckCircleIcon, 
  ArrowPathIcon,
  SpeakerWaveIcon,
  AcademicCapIcon,
  BookOpenIcon,
  SparklesIcon,
  NewspaperIcon,
  MicrophoneIcon,
  StopIcon,
  PlayIcon,
  CloudArrowDownIcon,
  ExclamationCircleIcon,
  Cog6ToothIcon,
  LinkIcon
} from '@heroicons/react/24/outline';

// 사용자가 제공한 기본 URL
const DEFAULT_GAS_URL = "https://script.google.com/macros/s/AKfycbzdQeSW5QEpi8B23vMKqtBtNDDkn3b_33vwrx_VKrY5WGF-WiT_UnO4pWOApLc2troQmA/exec";

const getTodayString = () => {
  const now = new Date();
  const offset = now.getTimezoneOffset() * 60000;
  return new Date(now.getTime() - offset).toISOString().split('T')[0];
};

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'study' | 'test' | 'record' | 'settings'>('study');
  const [gasUrl, setGasUrl] = useState<string>(DEFAULT_GAS_URL);
  const [testMode, setTestMode] = useState<'none' | 'today' | 'cumulative'>('none');
  const [todayRecord, setTodayRecord] = useState<DailyRecord>({
    date: getTodayString(),
    page: '',
    words: Array(13).fill({ word: '', meaning: '' }),
    newsContent: '',
    isCompleted: false,
  });
  const [history, setHistory] = useState<DailyRecord[]>([]);
  const [sheetWords, setSheetWords] = useState<WordEntry[]>([]);
  const [isLoadingSheet, setIsLoadingSheet] = useState(false);
  const [loadError, setLoadError] = useState<string | null>(null);

  const [testWords, setTestWords] = useState<WordEntry[]>([]);
  const [testStep, setTestStep] = useState(0);
  const [testResults, setTestResults] = useState<TestResult[]>([]);
  const [currentTestInput, setCurrentTestInput] = useState({ spelling: '', meaning: '' });
  const [isScoring, setIsScoring] = useState(false);

  // Recording states
  const [isRecording, setIsRecording] = useState(false);
  const [audioUrl, setAudioUrl] = useState<string | null>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);

  const calendarData = useMemo(() => {
    const now = new Date();
    const year = now.getFullYear();
    const month = now.getMonth();
    const firstDay = new Date(year, month, 1).getDay();
    const lastDate = new Date(year, month + 1, 0).getDate();
    const days = [];
    for (let i = 0; i < firstDay; i++) days.push(null);
    for (let i = 1; i <= lastDate; i++) {
      days.push({
        day: i,
        dateStr: `${year}-${String(month + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`
      });
    }
    return { days, month: month + 1, year };
  }, []);

  // 구글 시트 데이터 로드 (GET)
  const fetchSheetData = async (targetUrl: string = gasUrl) => {
    if (!targetUrl || !targetUrl.startsWith('https://')) return;

    setIsLoadingSheet(true);
    setLoadError(null);
    try {
      const url = `${targetUrl}?t=${Date.now()}`;
      // CORS 문제를 최소화하기 위해 헤더 없이 단순 GET 요청
      const response = await fetch(url);

      if (!response.ok) throw new Error(`서버 응답 오류: ${response.status}`);

      const data = await response.json();

      if (Array.isArray(data)) {
        const words: WordEntry[] = data
          .filter((item: any) => {
            const w = item.word || item.영어단어 || item.English;
            const skipWords = ["영어단어", "word", "english", "undefined", "null"];
            return w && String(w).trim() !== "" && !skipWords.includes(String(w).toLowerCase().trim());
          })
          .map((item: any) => ({
            word: String(item.word || item.영어단어 || item.English).trim(),
            meaning: String(item.meaning || item.의미 || item.Meaning).trim()
          }));

        const uniqueWordsMap = new Map();
        words.forEach(w => uniqueWordsMap.set(w.word.toLowerCase().trim(), w));

        const finalWords = Array.from(uniqueWordsMap.values());
        setSheetWords(finalWords);
        console.log(`Successfully synced ${finalWords.length} words.`);
      }
    } catch (error: any) {
      console.error("Fetch Error:", error);
      setLoadError("시트 데이터를 불러오지 못했습니다. 설정 탭에서 URL과 권한을 확인해주세요.");
    } finally {
      setIsLoadingSheet(false);
    }
  };

  useEffect(() => {
    // 1. 저장된 GAS URL 로드
    const savedUrl = localStorage.getItem('study_gas_url');
    const finalUrl = savedUrl || DEFAULT_GAS_URL;
    setGasUrl(finalUrl);

    // 2. 초기 데이터 페칭
    fetchSheetData(finalUrl);

    // 3. 로컬 학습 기록 로드
    const savedHistory = localStorage.getItem('study_history');
    if (savedHistory) {
      const parsed: DailyRecord[] = JSON.parse(savedHistory);
      setHistory(parsed);
      loadRecordForDate(todayRecord.date, parsed);
    }
  }, []);

  const loadRecordForDate = (dateStr: string, currentHistory: DailyRecord[]) => {
    const existing = currentHistory.find(r => r.date === dateStr);
    if (existing) {
      setTodayRecord(existing);
    } else {
      setTodayRecord({
        date: dateStr,
        page: '',
        words: Array(13).fill({ word: '', meaning: '' }),
        newsContent: '',
        isCompleted: false,
      });
    }
  };

  const saveGasUrl = () => {
    if (!gasUrl.trim().startsWith('https://script.google.com')) {
      alert("올바른 구글 앱스 스크립트 실행 URL이 아닙니다.");
      return;
    }
    localStorage.setItem('study_gas_url', gasUrl.trim());
    alert("설정이 저장되었습니다. 데이터를 다시 불러옵니다.");
    fetchSheetData(gasUrl.trim());
  };

  const handleDateChange = (newDate: string) => {
    loadRecordForDate(newDate, history);
  };

  const handleWordChange = (index: number, field: keyof WordEntry, value: string) => {
    const newWords = [...todayRecord.words];
    newWords[index] = { ...newWords[index], [field]: value };
    setTodayRecord({ ...todayRecord, words: newWords });
  };

  const submitStudy = async () => {
    const updatedRecord = { ...todayRecord, isCompleted: true };
    setTodayRecord(updatedRecord);
    const newHistory = [...history.filter(r => r.date !== todayRecord.date), updatedRecord];
    setHistory(newHistory);
    localStorage.setItem('study_history', JSON.stringify(newHistory));

    try {
      await fetch(gasUrl, {
        method: "POST",
        mode: "no-cors", 
        headers: { "Content-Type": "text/plain" },
        body: JSON.stringify(updatedRecord),
      });
      alert('시트로 전송되었습니다!');
      setTimeout(() => fetchSheetData(gasUrl), 1500);
    } catch (error) {
      alert('전송 중 오류가 발생했습니다.');
    }
  };

  const startTest = async (mode: 'today' | 'cumulative') => {
    let sourceWords: WordEntry[] = [];

    if (mode === 'today') {
      sourceWords = todayRecord.words.filter(w => w && w.word?.trim() !== "" && w.meaning?.trim() !== "");
      if (sourceWords.length === 0) {
        alert('오늘 기록된 단어가 없습니다!');
        return;
      }
    } else {
      const historyWords = history.flatMap(h => h.words || []).filter(w => w.word && w.word.trim() !== "");
      const combined = [...sheetWords, ...historyWords];
      const uniqueMap = new Map();
      combined.forEach(w => uniqueMap.set(w.word.toLowerCase().trim(), w));
      sourceWords = Array.from(uniqueMap.values());

      if (sourceWords.length === 0) {
        alert('테스트할 누적 단어가 없습니다. 먼저 시트 동기화를 확인해주세요.');
        return;
      }
    }

    const shuffled = [...sourceWords].sort(() => 0.5 - Math.random());
    const finalWords = mode === 'today' ? shuffled : shuffled.slice(0, Math.min(5, shuffled.length));

    setTestWords(finalWords);
    setTestStep(0);
    setTestResults([]);
    setCurrentTestInput({ spelling: '', meaning: '' });
    setTestMode(mode);
    setActiveTab('test');
  };

  const speakWord = (word: string) => {
    const utterance = new SpeechSynthesisUtterance(word);
    utterance.lang = 'en-US';
    window.speechSynthesis.speak(utterance);
  };

  const handleNextTest = async () => {
    if (isScoring) return;
    setIsScoring(true);
    const target = testWords[testStep];
    const score = await scoreTest(target.word, target.meaning, currentTestInput.spelling, currentTestInput.meaning);

    const result: TestResult = {
      word: target.word,
      userSpelling: currentTestInput.spelling,
      userMeaning: currentTestInput.meaning,
      isCorrect: score.isCorrect,
      feedback: score.feedback
    };

    setTestResults([...testResults, result]);
    setIsScoring(false);

    if (testStep < testWords.length - 1) {
      setTestStep(testStep + 1);
      setCurrentTestInput({ spelling: '', meaning: '' });
    }
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];
      mediaRecorder.ondataavailable = (e) => { if (e.data.size > 0) audioChunksRef.current.push(e.data); };
      mediaRecorder.onstop = () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/wav' });
        setAudioUrl(URL.createObjectURL(audioBlob));
      };
      mediaRecorder.start();
      setIsRecording(true);
    } catch (err) { alert("마이크 권한이 필요합니다."); }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      mediaRecorderRef.current.stream.getTracks().forEach(track => track.stop());
    }
  };

  return (
    <div className="min-h-screen pb-24 max-w-2xl mx-auto p-4 flex flex-col gap-6">
      <header className="flex flex-col gap-1 items-center py-6 bg-white rounded-3xl shadow-sm border border-slate-100 relative overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-indigo-500 via-purple-500 to-indigo-500 animate-gradient-x" />
        <div className="absolute top-4 right-4 flex items-center gap-2">
            <div className={`flex items-center gap-1 text-[10px] font-bold px-2 py-1 rounded-full ${loadError ? 'bg-red-50 text-red-500' : 'bg-green-50 text-green-600'}`}>
                {loadError ? <ExclamationCircleIcon className="w-3 h-3" /> : <div className="w-1.5 h-1.5 bg-green-500 rounded-full" />}
                {loadError ? '연결 오류' : `${sheetWords.length}단어`}
            </div>
            <button onClick={() => fetchSheetData()} className={`p-1.5 rounded-full hover:bg-slate-100 transition-all ${isLoadingSheet ? 'animate-spin' : ''}`}>
                <CloudArrowDownIcon className="w-5 h-5 text-indigo-400" />
            </button>
        </div>
        <h1 className="text-2xl font-bold text-indigo-600 flex items-center gap-2">
          <AcademicCapIcon className="w-8 h-8" />
          영어 학습 기록장
        </h1>
        <p className="text-slate-400 text-xs font-medium uppercase tracking-widest">Smart Vocabulary System</p>
      </header>

      <nav className="flex bg-white p-1 rounded-2xl shadow-sm border border-slate-100 sticky top-4 z-50">
        <button onClick={() => { setActiveTab('study'); setTestMode('none'); }} className={`flex-1 flex flex-col items-center py-3 rounded-xl transition-all ${activeTab === 'study' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}>
          <PencilSquareIcon className="w-6 h-6" />
          <span className="text-[10px] mt-1 font-bold">기록/수정</span>
        </button>
        <button onClick={() => { setActiveTab('test'); setTestMode('none'); }} className={`flex-1 flex flex-col items-center py-3 rounded-xl transition-all ${activeTab === 'test' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}>
          <ArrowPathIcon className="w-6 h-6" />
          <span className="text-[10px] mt-1 font-bold">테스트</span>
        </button>
        <button onClick={() => { setActiveTab('record'); setTestMode('none'); }} className={`flex-1 flex flex-col items-center py-3 rounded-xl transition-all ${activeTab === 'record' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}>
          <MicrophoneIcon className="w-6 h-6" />
          <span className="text-[10px] mt-1 font-bold">발음연습</span>
        </button>
        <button onClick={() => { setActiveTab('settings'); setTestMode('none'); }} className={`flex-1 flex flex-col items-center py-3 rounded-xl transition-all ${activeTab === 'settings' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}>
          <Cog6ToothIcon className="w-6 h-6" />
          <span className="text-[10px] mt-1 font-bold">설정</span>
        </button>
      </nav>

      <main className="flex-1">
