export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { WordEntry, DailyRecord, TestResult } from './types';
import { scoreTest } from './services/geminiService';
import { 
  CalendarIcon, 
  PencilSquareIcon, 
  CheckCircleIcon, 
  ArrowPathIcon,
  SpeakerWaveIcon,
  AcademicCapIcon,
  BookOpenIcon,
  SparklesIcon,
  NewspaperIcon,
  MicrophoneIcon,
  StopIcon,
  PlayIcon,
  CloudArrowDownIcon,
  ExclamationCircleIcon,
  Cog6ToothIcon,
  LinkIcon
} from '@heroicons/react/24/outline';

// 사용자가 새로 제공한 기본 URL (AKfycbwqJNte9iEsNvW_5CWwyxkdxYazw7nTQ_cH2W0GYQwqDDWFSReQII1xLXwXNSoxOfuGIA/exec)
const DEFAULT_GAS_URL = "https://script.google.com/macros/s/AKfycbwqJNte9iEsNvW_5CWwyxkdxYazw7nTQ_cH2W0GYQwqDDWFSReQII1xLXwXNSoxOfuGIA/exec";

const getTodayString = () => {
  const now = new Date();
  const offset = now.getTimezoneOffset() * 60000;
  return new Date(now.getTime() - offset).toISOString().split('T')[0];
};

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'study' | 'test' | 'record' | 'settings'>('study');
  const [gasUrl, setGasUrl] = useState<string>(DEFAULT_GAS_URL);
  const [testMode, setTestMode] = useState<'none' | 'today' | 'cumulative'>('none');
  const [todayRecord, setTodayRecord] = useState<DailyRecord>({
    date: getTodayString(),
    page: '',
    words: Array(13).fill({ word: '', meaning: '' }),
    newsContent: '',
    isCompleted: false,
  });
  const [history, setHistory] = useState<DailyRecord[]>([]);
  const [sheetWords, setSheetWords] = useState<WordEntry[]>([]);
  const [isLoadingSheet, setIsLoadingSheet] = useState(false);
  const [loadError, setLoadError] = useState<string | null>(null);

  const [testWords, setTestWords] = useState<WordEntry[]>([]);
  const [testStep, setTestStep] = useState(0);
  const [testResults, setTestResults] = useState<TestResult[]>([]);
  const [currentTestInput, setCurrentTestInput] = useState({ spelling: '', meaning: '' });
  const [isScoring, setIsScoring] = useState(false);

  // Recording states
  const [isRecording, setIsRecording] = useState(false);
  const [audioUrl, setAudioUrl] = useState<string | null>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);

  const calendarData = useMemo(() => {
    const now = new Date();
    const year = now.getFullYear();
    const month = now.getMonth();
    const firstDay = new Date(year, month, 1).getDay();
    const lastDate = new Date(year, month + 1, 0).getDate();
    const days = [];
    for (let i = 0; i < firstDay; i++) days.push(null);
    for (let i = 1; i <= lastDate; i++) {
      days.push({
        day: i,
        dateStr: `${year}-${String(month + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`
      });
    }
    return { days, month: month + 1, year };
  }, []);

  // 구글 시트 데이터 로드 (GET)
  const fetchSheetData = async (targetUrl: string = gasUrl) => {
    if (!targetUrl || !targetUrl.startsWith('https://')) return;

    setIsLoadingSheet(true);
    setLoadError(null);
    try {
      const url = `${targetUrl}?t=${Date.now()}`;
      const response = await fetch(url);

      if (!response.ok) throw new Error(`서버 응답 오류: ${response.status}`);

      const data = await response.json();

      if (Array.isArray(data)) {
        // 시트 데이터 매핑 (한글 헤더 우선 인식)
        const words: WordEntry[] = data
          .map((item: any) => {
            // 한글/영어 다양한 헤더 이름을 체크
            const word = item.영어단어 || item.word || item.English || item.Word;
            const meaning = item.의미 || item.meaning || item.Meaning || item.Definition;
            return {
              word: word ? String(word).trim() : "",
              meaning: meaning ? String(meaning).trim() : ""
            };
          })
          .filter((w) => {
            // 유효한 단어와 의미가 있고, 헤더 텍스트 자체가 아닌 것 필터링
            const skipLabels = ["영어단어", "word", "english", "의미", "meaning"];
            return (
              w.word !== "" && 
              w.meaning !== "" && 
              !skipLabels.includes(w.word.toLowerCase())
            );
          });

        // 중복 제거 (대소문자 구분 없이)
        const uniqueWordsMap = new Map();
        words.forEach(w => uniqueWordsMap.set(w.word.toLowerCase(), w));

        const finalWords = Array.from(uniqueWordsMap.values());
        setSheetWords(finalWords);
        console.log("Synced Words:", finalWords);
      }
    } catch (error: any) {
      console.error("Fetch Error:", error);
      setLoadError("시트 데이터를 불러오지 못했습니다. 설정에서 URL을 확인해주세요.");
    } finally {
      setIsLoadingSheet(false);
    }
  };

  useEffect(() => {
    const savedUrl = localStorage.getItem('study_gas_url');
    const finalUrl = savedUrl || DEFAULT_GAS_URL;
    setGasUrl(finalUrl);
    fetchSheetData(finalUrl);

    const savedHistory = localStorage.getItem('study_history');
    if (savedHistory) {
      const parsed: DailyRecord[] = JSON.parse(savedHistory);
      setHistory(parsed);
      loadRecordForDate(todayRecord.date, parsed);
    }
  }, []);

  const loadRecordForDate = (dateStr: string, currentHistory: DailyRecord[]) => {
    const existing = currentHistory.find(r => r.date === dateStr);
    if (existing) {
      setTodayRecord(existing);
    } else {
      setTodayRecord({
        date: dateStr,
        page: '',
        words: Array(13).fill({ word: '', meaning: '' }),
        newsContent: '',
        isCompleted: false,
      });
    }
  };

  const saveGasUrl = () => {
    if (!gasUrl.trim().startsWith('https://script.google.com')) {
      alert("올바른 구글 앱스 스크립트 실행 URL이 아닙니다.");
      return;
    }
    localStorage.setItem('study_gas_url', gasUrl.trim());
    alert("URL이 변경되었습니다. 데이터를 새로 불러옵니다.");
    fetchSheetData(gasUrl.trim());
  };

  const handleDateChange = (newDate: string) => {
    loadRecordForDate(newDate, history);
  };

  const handleWordChange = (index: number, field: keyof WordEntry, value: string) => {
    const newWords = [...todayRecord.words];
    newWords[index] = { ...newWords[index], [field]: value };
    setTodayRecord({ ...todayRecord, words: newWords });
  };

  const submitStudy = async () => {
    const updatedRecord = { ...todayRecord, isCompleted: true };
    setTodayRecord(updatedRecord);
    const newHistory = [...history.filter(r => r.date !== todayRecord.date), updatedRecord];
    setHistory(newHistory);
    localStorage.setItem('study_history', JSON.stringify(newHistory));

    try {
      await fetch(gasUrl, {
        method: "POST",
        mode: "no-cors", 
        headers: { "Content-Type": "text/plain" },
        body: JSON.stringify(updatedRecord),
      });
      alert('시트로 전송되었습니다!');
      setTimeout(() => fetchSheetData(gasUrl), 2000);
    } catch (error) {
      alert('전송 중 오류가 발생했습니다.');
    }
  };

  const startTest = async (mode: 'today' | 'cumulative') => {
    let sourceWords: WordEntry[] = [];

    if (mode === 'today') {
      sourceWords = todayRecord.words.filter(w => w && w.word?.trim() !== "" && w.meaning?.trim() !== "");
      if (sourceWords.length === 0) {
        alert('오늘 입력한 단어가 없습니다!');
        return;
      }
    } else {
      // 누적 테스트는 시트에서 불러온 sheetWords를 사용
      if (sheetWords.length === 0) {
        alert('시트에서 불러온 누적 단어가 없습니다. 동기화 버튼을 누르거나 설정을 확인하세요.');
        return;
      }
      sourceWords = sheetWords;
    }

    const shuffled = [...sourceWords].sort(() => 0.5 - Math.random());
    const finalWords = mode === 'today' ? shuffled : shuffled.slice(0, Math.min(5, shuffled.length));

    setTestWords(finalWords);
    setTestStep(0);
    setTestResults([]);
    setCurrentTestInput({ spelling: '', meaning: '' });
    setTestMode(mode);
    setActiveTab('test');
  };

  const speakWord = (word: string) => {
    const utterance = new SpeechSynthesisUtterance(word);
    utterance.lang = 'en-US';
    window.speechSynthesis.speak(utterance);
  };

  const handleNextTest = async () => {
    if (isScoring) return;
    setIsScoring(true);
    const target = testWords[testStep];
    const score = await scoreTest(target.word, target.meaning, currentTestInput.spelling, currentTestInput.meaning);

    const result: TestResult = {
      word: target.word,
      userSpelling: currentTestInput.spelling,
      userMeaning: currentTestInput.meaning,
      isCorrect: score.isCorrect,
      feedback: score.feedback
    };

    setTestResults([...testResults, result]);
    setIsScoring(false);

    if (testStep < testWords.length - 1) {
      setTestStep(testStep + 1);
      setCurrentTestInput({ spelling: '', meaning: '' });
    }
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];
      mediaRecorder.ondataavailable = (e) => { if (e.data.size > 0) audioChunksRef.current.push(e.data); };
      mediaRecorder.onstop = () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/wav' });
        setAudioUrl(URL.createObjectURL(audioBlob));
      };
      mediaRecorder.start();
      setIsRecording(true);
    } catch (err) { alert("마이크 권한이 필요합니다."); }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      mediaRecorderRef.current.stream.getTracks().forEach(track => track.stop());
    }
  };

  return (
    <div className="min-h-screen pb-24 max-w-2xl mx-auto p-4 flex flex-col gap-6">
      <header className="flex flex-col gap-1 items-center py-6 bg-white rounded-3xl shadow-sm border border-slate-100 relative overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-indigo-500 via-purple-500 to-indigo-500 animate-gradient-x" />
        <div className="absolute top-4 right-4 flex items-center gap-2">
            <div className={`flex items-center gap-1 text-[10px] font-bold px-2 py-1 rounded-full ${loadError ? 'bg-red-50 text-red-500' : 'bg-green-50 text-green-600'}`}>
                {loadError ? <ExclamationCircleIcon className="w-3 h-3" /> : <div className="w-1.5 h-1.5 bg-green-500 rounded-full" />}
                {loadError ? '연결 오류' : `${sheetWords.length}단어`}
            </div>
            <button onClick={() => fetchSheetData()} className={`p-1.5 rounded-full hover:bg-slate-100 transition-all ${isLoadingSheet ? 'animate-spin' : ''}`}>
                <CloudArrowDownIcon className="w-5 h-5 text-indigo-400" />
            </button>
        </div>
        <h1 className="text-2xl font-bold text-indigo-600 flex items-center gap-2">
          <AcademicCapIcon className="w-8 h-8" />
          영어 학습 기록장
        </h1>
        <p className="text-slate-400 text-xs font-medium uppercase tracking-widest">누가기록 기반 인공지능 학습</p>
      </header>

      <nav className="flex bg-white p-1 rounded-2xl shadow-sm border border-slate-100 sticky top-4 z-50">
        <button onClick={() => { setActiveTab('study'); setTestMode('none'); }} className={`flex-1 flex flex-col items-center py-3 rounded-xl transition-all ${activeTab === 'study' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}>
          <PencilSquareIcon className="w-6 h-6" />
          <span className="text-[10px] mt-1 font-bold">기록/수정</span>
        </button>
        <button onClick={() => { setActiveTab('test'); setTestMode('none'); }} className={`flex-1 flex flex-col items-center py-3 rounded-xl transition-all ${activeTab === 'test' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}>
          <ArrowPathIcon className="w-6 h-6" />
          <span className="text-[10px] mt-1 font-bold">테스트</span>
        </button>
        <button onClick={() => { setActiveTab('record'); setTestMode('none'); }} className={`flex-1 flex flex-col items-center py-3 rounded-xl transition-all ${activeTab === 'record' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}>
          <MicrophoneIcon className="w-6 h-6" />
          <span className="text-[10px] mt-1 font-bold">발음연습</span>
        </button>
        <button onClick={() => { setActiveTab('settings'); setTestMode('none'); }} className={`flex-1 flex flex-col items-center py-3 rounded-xl transition-all ${activeTab === 'settings' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}>
          <Cog6ToothIcon className="w-6 h-6" />
          <span className="text-[10px] mt-1 font-bold">설정</span>
        </button>
      </nav>

      <main className="flex-1">
        {activeTab === 'study' && (
          <div className="flex flex-col gap-6 animate-fadeIn">
            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 space-y-4">
               <div className="flex justify-between items-center border-b border-slate-50 pb-4">
                 <h2 className="text-lg font-bold text-slate-800">기록 정보</h2>
                 <span className={`px-4 py-1 rounded-full text-[11px] font-bold ${todayRecord.isCompleted ? 'bg-green-100 text-green-700' : 'bg-amber-100 text-amber-700'}`}>
                    {todayRecord.isCompleted ? '학습완료' : '기록중'}
                 </span>
               </div>
               <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">학습 날짜</label>
                    <input type="date" value={todayRecord.date} onChange={(e) => handleDateChange(e.target.value)} className="w-full bg-slate-50 border border-slate-100 rounded-lg px-2 py-2 text-sm font-bold text-slate-700 outline-none" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">범위 (페이지)</label>
                    <input type="text" placeholder="예: 10-15" disabled={todayRecord.isCompleted} value={todayRecord.page} onChange={(e) => setTodayRecord({...todayRecord, page: e.target.value})} className="w-full bg-slate-50 border border-slate-100 rounded-lg px-2 py-2 text-sm outline-none" />
                  </div>
               </div>
            </div>

            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 space-y-3">
              <h3 className="font-bold text-slate-700 flex items-center gap-2"><NewspaperIcon className="w-5 h-5 text-indigo-500" />영자신문 읽기</h3>
              <textarea placeholder="오늘 읽은 뉴스 기사의 주요 내용이나 소감을 적으세요..." disabled={todayRecord.isCompleted} value={todayRecord.newsContent} onChange={(e) => setTodayRecord({...todayRecord, newsContent: e.target.value})} className="w-full bg-slate-50 border border-slate-100 rounded-xl px-4 py-3 text-sm min-h-[100px] outline-none" />
            </div>

            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 space-y-3">
              <h3 className="font-bold text-slate-700">단어 기록 (13개)</h3>
              <div className="grid grid-cols-1 gap-2">
                {todayRecord.words.map((w, idx) => (
                  <div key={idx} className="flex gap-2 items-center">
                    <span className="w-5 text-[10px] font-bold text-slate-300">{idx + 1}</span>
                    <input type="text" placeholder="Word" disabled={todayRecord.isCompleted} value={w.word} onChange={(e) => handleWordChange(idx, 'word', e.target.value)} className="flex-1 bg-slate-50 border border-slate-100 rounded-xl px-3 py-2 text-sm outline-none focus:ring-1 focus:ring-indigo-300" />
