                  </button>
                ) : (
                  <button onClick={stopRecording} className="bg-red-600 text-white font-bold px-10 py-5 rounded-[1.5rem] shadow-lg hover:bg-red-700 transition-all flex items-center gap-2">
                    <StopIcon className="w-5 h-5" /> 녹음 중지
                  </button>
                )}
              </div>
              {audioUrl && !isRecording && (
                <div className="pt-8 border-t border-slate-50 space-y-4">
                  <div className="flex items-center justify-center gap-5">
