                     💡 <b>도움말:</b> URL을 변경한 후 <b>'저장'</b> 버튼을 누르면 시트의 모든 단어를 즉시 동기화합니다. "영어단어", "의미" 헤더가 있는 시트여야 합니다.
                   </p>
                 </div>
                 <button onClick={saveGasUrl} className="w-full bg-indigo-600 text-white font-bold py-5 rounded-[1.5rem] shadow-lg hover:bg-indigo-700 transition-all active:scale-[0.98]">
                    설정 저장 및 다시 동기화
                 </button>
               </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { WordEntry, DailyRecord, TestResult } from './types';
import { scoreTest } from './services/geminiService';
import { 
  CalendarIcon, 
  PencilSquareIcon, 
  CheckCircleIcon, 
  ArrowPathIcon,
  SpeakerWaveIcon,
  AcademicCapIcon,
  BookOpenIcon,
  SparklesIcon,
  NewspaperIcon,
  MicrophoneIcon,
  StopIcon,
  PlayIcon,
  CloudArrowDownIcon,
  ExclamationCircleIcon,
  Cog6ToothIcon,
  LinkIcon
} from '@heroicons/react/24/outline';

// 사용자가 제공한 최신 GAS URL
const DEFAULT_GAS_URL = "https://script.google.com/macros/s/AKfycbwqJNte9iEsNvW_5CWwyxkdxYazw7nTQ_cH2W0GYQwqDDWFSReQII1xLXwXNSoxOfuGIA/exec";

const getTodayString = () => {
  const now = new Date();
  const offset = now.getTimezoneOffset() * 60000;
  return new Date(now.getTime() - offset).toISOString().split('T')[0];
};

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'study' | 'test' | 'record' | 'settings'>('study');
  const [gasUrl, setGasUrl] = useState<string>(DEFAULT_GAS_URL);
  const [testMode, setTestMode] = useState<'none' | 'today' | 'cumulative'>('none');
  const [todayRecord, setTodayRecord] = useState<DailyRecord>({
    date: getTodayString(),
    page: '',
    words: Array(13).fill({ word: '', meaning: '' }),
    newsContent: '',
    isCompleted: false,
  });
  const [history, setHistory] = useState<DailyRecord[]>([]);
  const [sheetWords, setSheetWords] = useState<WordEntry[]>([]);
  const [isLoadingSheet, setIsLoadingSheet] = useState(false);
  const [loadError, setLoadError] = useState<string | null>(null);

  const [testWords, setTestWords] = useState<WordEntry[]>([]);
  const [testStep, setTestStep] = useState(0);
  const [testResults, setTestResults] = useState<TestResult[]>([]);
  const [currentTestInput, setCurrentTestInput] = useState({ spelling: '', meaning: '' });
  const [isScoring, setIsScoring] = useState(false);

  // Recording states
  const [isRecording, setIsRecording] = useState(false);
  const [audioUrl, setAudioUrl] = useState<string | null>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);

  const calendarData = useMemo(() => {
    const now = new Date();
    const year = now.getFullYear();
    const month = now.getMonth();
    const firstDay = new Date(year, month, 1).getDay();
    const lastDate = new Date(year, month + 1, 0).getDate();
    const days = [];
    for (let i = 0; i < firstDay; i++) days.push(null);
    for (let i = 1; i <= lastDate; i++) {
      days.push({
        day: i,
        dateStr: `${year}-${String(month + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`
      });
    }
    return { days, month: month + 1, year };
  }, []);

  // 구글 시트 데이터 로드 및 파싱 로직 강화
  const fetchSheetData = async (targetUrl: string = gasUrl) => {
    if (!targetUrl || !targetUrl.startsWith('https://')) return;

    setIsLoadingSheet(true);
    setLoadError(null);
    try {
      const url = `${targetUrl}?t=${Date.now()}`;
      const response = await fetch(url);

      if (!response.ok) throw new Error(`서버 응답 오류: ${response.status}`);

      const rawData = await response.json();

      // GAS가 { data: [...] } 형태로 보내거나 단순 배열 [...]로 보낼 경우 모두 대응
      const dataArray = Array.isArray(rawData) ? rawData : (rawData.data && Array.isArray(rawData.data) ? rawData.data : []);

      if (dataArray.length > 0) {
        const parsedWords: WordEntry[] = dataArray
          .map((item: any) => {
            // 한글 헤더 및 영어 헤더를 매우 유연하게 매핑
            const word = item["영어단어"] || item.영어단어 || item.word || item.Word || item.English || item.english || "";
            const meaning = item["의미"] || item.의미 || item.meaning || item.Meaning || item.Definition || item.definition || "";
            return {
              word: String(word).trim(),
              meaning: String(meaning).trim()
            };
          })
          .filter((w) => {
            const isHeader = ["영어단어", "word", "의미", "meaning"].includes(w.word.toLowerCase());
            return w.word.length > 0 && w.meaning.length > 0 && !isHeader;
          });

        // 중복 제거
        const uniqueMap = new Map();
        parsedWords.forEach(w => uniqueMap.set(w.word.toLowerCase(), w));
        const finalWords = Array.from(uniqueMap.values());

        setSheetWords(finalWords);
        console.log("Sheet Sync Success:", finalWords.length, "words loaded.");
      } else {
        console.warn("Sheet returned empty data array.");
      }
    } catch (error: any) {
      console.error("Fetch Error Details:", error);
      setLoadError("시트 데이터를 가져오지 못했습니다. URL을 확인하거나 다시 시도해주세요.");
    } finally {
      setIsLoadingSheet(false);
    }
  };

  useEffect(() => {
    const savedUrl = localStorage.getItem('study_gas_url');
    const finalUrl = savedUrl || DEFAULT_GAS_URL;
    setGasUrl(finalUrl);
    fetchSheetData(finalUrl);

    const savedHistory = localStorage.getItem('study_history');
    if (savedHistory) {
      const parsed: DailyRecord[] = JSON.parse(savedHistory);
      setHistory(parsed);
      loadRecordForDate(todayRecord.date, parsed);
    }
  }, []);

  const loadRecordForDate = (dateStr: string, currentHistory: DailyRecord[]) => {
    const existing = currentHistory.find(r => r.date === dateStr);
    if (existing) {
      setTodayRecord(existing);
    } else {
      setTodayRecord({
        date: dateStr,
        page: '',
        words: Array(13).fill({ word: '', meaning: '' }),
        newsContent: '',
        isCompleted: false,
      });
    }
  };

  const saveGasUrl = () => {
    const cleanUrl = gasUrl.trim();
    if (!cleanUrl.startsWith('https://script.google.com')) {
      alert("올바른 구글 앱스 스크립트 실행 URL이 아닙니다.");
      return;
    }
    localStorage.setItem('study_gas_url', cleanUrl);
    alert("설정이 저장되었습니다. 데이터를 동기화합니다.");
    fetchSheetData(cleanUrl);
  };

  const handleDateChange = (newDate: string) => {
    loadRecordForDate(newDate, history);
  };

  const handleWordChange = (index: number, field: keyof WordEntry, value: string) => {
    const newWords = [...todayRecord.words];
    newWords[index] = { ...newWords[index], [field]: value };
    setTodayRecord({ ...todayRecord, words: newWords });
  };

  const submitStudy = async () => {
    const updatedRecord = { ...todayRecord, isCompleted: true };
    setTodayRecord(updatedRecord);
    const newHistory = [...history.filter(r => r.date !== todayRecord.date), updatedRecord];
    setHistory(newHistory);
    localStorage.setItem('study_history', JSON.stringify(newHistory));

    try {
      await fetch(gasUrl, {
        method: "POST",
        mode: "no-cors", 
        headers: { "Content-Type": "text/plain" },
        body: JSON.stringify(updatedRecord),
      });
      alert('시트로 학습 기록이 전송되었습니다!');
      // 전송 후 시트 데이터 갱신 (약간의 지연 필요)
      setTimeout(() => fetchSheetData(gasUrl), 2000);
    } catch (error) {
      alert('시트 전송 중 오류가 발생했습니다.');
    }
  };

  // 누적 랜덤 테스트 로직 (시트 데이터 + 로컬 기록 통합)
  const startTest = async (mode: 'today' | 'cumulative') => {
    let sourceWords: WordEntry[] = [];

    if (mode === 'today') {
      sourceWords = todayRecord.words.filter(w => w && w.word?.trim() !== "" && w.meaning?.trim() !== "");
      if (sourceWords.length === 0) {
        alert('오늘 입력한 단어가 없습니다. 단어를 먼저 입력해주세요.');
        return;
      }
    } else {
      // 누적 테스트 소스 통합 (시트 데이터 + 로컬 히스토리)
      const localHistoryWords = history.flatMap(h => h.words || []).filter(w => w.word && w.word.trim() !== "");
      const combined = [...sheetWords, ...localHistoryWords];

      // 중복 제거
      const uniqueMap = new Map();
      combined.forEach(w => uniqueMap.set(w.word.toLowerCase().trim(), w));
      sourceWords = Array.from(uniqueMap.values());

      if (sourceWords.length === 0) {
        alert('테스트할 누적 단어가 없습니다. 시트 동기화를 확인하거나 학습을 먼저 완료해주세요.');
        setActiveTab('settings');
        return;
      }
    }

    const shuffled = [...sourceWords].sort(() => 0.5 - Math.random());
    const finalWords = mode === 'today' ? shuffled : shuffled.slice(0, Math.min(5, shuffled.length));

    setTestWords(finalWords);
    setTestStep(0);
    setTestResults([]);
    setCurrentTestInput({ spelling: '', meaning: '' });
    setTestMode(mode);
    setActiveTab('test');
  };

  const speakWord = (word: string) => {
    const utterance = new SpeechSynthesisUtterance(word);
    utterance.lang = 'en-US';
    window.speechSynthesis.speak(utterance);
  };

  const handleNextTest = async () => {
    if (isScoring) return;
    setIsScoring(true);
    const target = testWords[testStep];
    const score = await scoreTest(target.word, target.meaning, currentTestInput.spelling, currentTestInput.meaning);

    const result: TestResult = {
      word: target.word,
      userSpelling: currentTestInput.spelling,
      userMeaning: currentTestInput.meaning,
      isCorrect: score.isCorrect,
      feedback: score.feedback
    };

    setTestResults([...testResults, result]);
    setIsScoring(false);

    if (testStep < testWords.length - 1) {
      setTestStep(testStep + 1);
      setCurrentTestInput({ spelling: '', meaning: '' });
    }
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];
      mediaRecorder.ondataavailable = (e) => { if (e.data.size > 0) audioChunksRef.current.push(e.data); };
      mediaRecorder.onstop = () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/wav' });
        setAudioUrl(URL.createObjectURL(audioBlob));
      };
      mediaRecorder.start();
      setIsRecording(true);
    } catch (err) { alert("마이크 권한이 필요합니다."); }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      mediaRecorderRef.current.stream.getTracks().forEach(track => track.stop());
    }
  };

  // 누적 단어 총합 계산 (UI 표시용)
  const totalCumulativeCount = useMemo(() => {
    const localHistoryWords = history.flatMap(h => h.words || []).filter(w => w.word && w.word.trim() !== "");
    const combined = [...sheetWords, ...localHistoryWords];
    const uniqueMap = new Map();
    combined.forEach(w => uniqueMap.set(w.word.toLowerCase().trim(), w));
    return uniqueMap.size;
  }, [sheetWords, history]);

  return (
    <div className="min-h-screen pb-24 max-w-2xl mx-auto p-4 flex flex-col gap-6">
      <header className="flex flex-col gap-1 items-center py-6 bg-white rounded-3xl shadow-sm border border-slate-100 relative overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-indigo-500 via-purple-500 to-indigo-500 animate-gradient-x" />
        <div className="absolute top-4 right-4 flex items-center gap-2">
            <div className={`flex items-center gap-1 text-[10px] font-bold px-2 py-1 rounded-full ${loadError ? 'bg-red-50 text-red-500' : 'bg-green-50 text-green-600'}`}>
                {loadError ? <ExclamationCircleIcon className="w-3 h-3" /> : <div className="w-1.5 h-1.5 bg-green-500 rounded-full" />}
                {loadError ? '연결 오류' : `${totalCumulativeCount}단어`}
            </div>
            <button onClick={() => fetchSheetData()} className={`p-1.5 rounded-full hover:bg-slate-100 transition-all ${isLoadingSheet ? 'animate-spin' : ''}`}>
                <CloudArrowDownIcon className="w-5 h-5 text-indigo-400" />
            </button>
        </div>
        <h1 className="text-2xl font-bold text-indigo-600 flex items-center gap-2">
          <AcademicCapIcon className="w-8 h-8" />
          영어 학습 기록장
        </h1>
        <p className="text-slate-400 text-xs font-medium uppercase tracking-widest">누가기록 기반 인공지능 학습</p>
      </header>

      <nav className="flex bg-white p-1 rounded-2xl shadow-sm border border-slate-100 sticky top-4 z-50">
        <button onClick={() => { setActiveTab('study'); setTestMode('none'); }} className={`flex-1 flex flex-col items-center py-3 rounded-xl transition-all ${activeTab === 'study' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}>
          <PencilSquareIcon className="w-6 h-6" />
          <span className="text-[10px] mt-1 font-bold">기록/수정</span>
        </button>
        <button onClick={() => { setActiveTab('test'); setTestMode('none'); }} className={`flex-1 flex flex-col items-center py-3 rounded-xl transition-all ${activeTab === 'test' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}>
          <ArrowPathIcon className="w-6 h-6" />
          <span className="text-[10px] mt-1 font-bold">테스트</span>
        </button>
        <button onClick={() => { setActiveTab('record'); setTestMode('none'); }} className={`flex-1 flex flex-col items-center py-3 rounded-xl transition-all ${activeTab === 'record' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}>
          <MicrophoneIcon className="w-6 h-6" />
          <span className="text-[10px] mt-1 font-bold">발음연습</span>
        </button>
        <button onClick={() => { setActiveTab('settings'); setTestMode('none'); }} className={`flex-1 flex flex-col items-center py-3 rounded-xl transition-all ${activeTab === 'settings' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}>
          <Cog6ToothIcon className="w-6 h-6" />
          <span className="text-[10px] mt-1 font-bold">설정</span>
        </button>
      </nav>

      <main className="flex-1">
        {activeTab === 'study' && (
          <div className="flex flex-col gap-6 animate-fadeIn">
            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 space-y-4">
               <div className="flex justify-between items-center border-b border-slate-50 pb-4">
                 <h2 className="text-lg font-bold text-slate-800">기록 정보</h2>
                 <span className={`px-4 py-1 rounded-full text-[11px] font-bold ${todayRecord.isCompleted ? 'bg-green-100 text-green-700' : 'bg-amber-100 text-amber-700'}`}>
                    {todayRecord.isCompleted ? '학습완료' : '기록중'}
                 </span>
               </div>
               <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">학습 날짜</label>
                    <input type="date" value={todayRecord.date} onChange={(e) => handleDateChange(e.target.value)} className="w-full bg-slate-50 border border-slate-100 rounded-lg px-2 py-2 text-sm font-bold text-slate-700 outline-none focus:ring-1 focus:ring-indigo-300" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">범위 (페이지)</label>
                    <input type="text" placeholder="예: 10-15" disabled={todayRecord.isCompleted} value={todayRecord.page} onChange={(e) => setTodayRecord({...todayRecord, page: e.target.value})} className="w-full bg-slate-50 border border-slate-100 rounded-lg px-2 py-2 text-sm outline-none focus:ring-1 focus:ring-indigo-300" />
                  </div>
               </div>
            </div>

            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 space-y-3">
              <h3 className="font-bold text-slate-700 flex items-center gap-2"><NewspaperIcon className="w-5 h-5 text-indigo-500" />영자신문 읽기</h3>
              <textarea placeholder="오늘 읽은 뉴스 기사의 주요 내용이나 소감을 적으세요..." disabled={todayRecord.isCompleted} value={todayRecord.newsContent} onChange={(e) => setTodayRecord({...todayRecord, newsContent: e.target.value})} className="w-full bg-slate-50 border border-slate-100 rounded-xl px-4 py-3 text-sm min-h-[100px] outline-none focus:ring-1 focus:ring-indigo-300 transition-all" />
            </div>

            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 space-y-3">
              <h3 className="font-bold text-slate-700">단어 기록 (13개)</h3>
              <div className="grid grid-cols-1 gap-2">
                {todayRecord.words.map((w, idx) => (
                  <div key={idx} className="flex gap-2 items-center">
                    <span className="w-5 text-[10px] font-bold text-slate-300">{idx + 1}</span>
                    <input type="text" placeholder="Word" disabled={todayRecord.isCompleted} value={w.word} onChange={(e) => handleWordChange(idx, 'word', e.target.value)} className="flex-1 bg-slate-50 border border-slate-100 rounded-xl px-3 py-2 text-sm outline-none focus:ring-1 focus:ring-indigo-300 transition-all" />
                    <input type="text" placeholder="뜻" disabled={todayRecord.isCompleted} value={w.meaning} onChange={(e) => handleWordChange(idx, 'meaning', e.target.value)} className="flex-1 bg-slate-50 border border-slate-100 rounded-xl px-3 py-2 text-sm outline-none focus:ring-1 focus:ring-indigo-300 transition-all" />
                  </div>
                ))}
              </div>
              <div className="pt-6">
                {todayRecord.isCompleted ? (
                  <button onClick={() => setTodayRecord({...todayRecord, isCompleted: false})} className="w-full bg-slate-100 text-slate-600 font-bold py-4 rounded-2xl flex items-center justify-center gap-2 hover:bg-slate-200 transition-all active:scale-[0.98]">
                    <PencilSquareIcon className="w-5 h-5" /> 내용 수정하기
                  </button>
                ) : (
                  <button onClick={submitStudy} className="w-full bg-indigo-600 text-white font-bold py-4 rounded-2xl shadow-lg flex items-center justify-center gap-2 hover:bg-indigo-700 transition-all active:scale-[0.98]">
                    <CheckCircleIcon className="w-5 h-5" /> 학습완료 제출 (시트 저장)
                  </button>
                )}
              </div>
            </div>

            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
              <h2 className="text-lg font-bold mb-6 text-slate-800 flex items-center gap-2"><CalendarIcon className="w-6 h-6 text-indigo-500" />학습 진행 달력</h2>
              <div className="grid grid-cols-7 gap-2 text-center">
                {['일','월','화','수','목','금','토'].map(d => (<div key={d} className="text-[10px] font-bold text-slate-400 py-2 uppercase tracking-tighter">{d}</div>))}
                {calendarData.days.map((dayObj, i) => {
                  if (!dayObj) return <div key={`empty-${i}`} />;
                  const record = history.find(r => r.date === dayObj.dateStr);
                  const isFinished = record && record.isCompleted;
                  const isSelected = dayObj.dateStr === todayRecord.date;
                  return (
                    <button key={i} onClick={() => handleDateChange(dayObj.dateStr)} className={`aspect-square flex flex-col items-center justify-center rounded-2xl border transition-all ${isFinished ? 'bg-green-50 border-green-100' : isSelected ? 'bg-indigo-600 border-indigo-600 text-white shadow-md' : 'bg-slate-50 border-slate-50 hover:bg-slate-100'}`}>
                      <span className={`text-[11px] font-bold ${isSelected ? 'text-white' : isFinished ? 'text-green-700' : 'text-slate-500'}`}>{dayObj.day}</span>
                      {isFinished && !isSelected && <div className="text-[7px] font-bold text-green-500 mt-0.5">완료</div>}
                    </button>
                  );
                })}
              </div>
            </div>
          </div>
        )}

        {activeTab === 'test' && (
          <div className="animate-fadeIn">
            {testMode === 'none' ? (
              <div className="grid grid-cols-1 gap-6">
                {(loadError || (totalCumulativeCount === 0 && !isLoadingSheet)) && (
                  <div className="bg-red-50 border border-red-100 p-5 rounded-3xl flex items-start gap-3 shadow-sm">
                    <ExclamationCircleIcon className="w-6 h-6 text-red-500 shrink-0 mt-0.5" />
                    <div className="flex-1">
                      <p className="text-sm font-bold text-red-800">테스트 데이터가 없습니다</p>
                      <p className="text-xs text-red-600 leading-relaxed mt-1">시트에서 단어를 불러오지 못했거나 저장된 학습 기록이 없습니다. 설정 탭에서 URL을 확인하거나 학습을 완료해 주세요.</p>
                      <button onClick={() => setActiveTab('settings')} className="text-xs font-bold text-red-500 underline mt-3 flex items-center gap-1">
                        <LinkIcon className="w-3 h-3" /> 설정 및 동기화 확인하기
                      </button>
                    </div>
                  </div>
                )}

                <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border border-slate-100 text-center space-y-5">
                  <BookOpenIcon className="w-12 h-12 text-indigo-600 mx-auto" />
                  <div>
                    <h2 className="text-xl font-bold text-slate-800">오늘의 단어 테스트</h2>
                    <p className="text-slate-500 text-sm mt-1">오늘 입력한 {todayRecord.words.filter(w=>w.word).length}개의 단어를 시험 봅니다.</p>
                  </div>
                  <button onClick={() => startTest('today')} className="w-full bg-indigo-600 text-white font-bold py-5 rounded-[1.5rem] shadow-lg hover:bg-indigo-700 transition-all active:scale-[0.98]">오늘 시험 시작</button>
                </div>

                <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border border-slate-100 text-center space-y-5">
                  <SparklesIcon className="w-12 h-12 text-violet-600 mx-auto" />
                  <div>
                    <h2 className="text-xl font-bold text-slate-800">누적 랜덤 테스트</h2>
                    <p className="text-slate-500 text-sm mt-1">시트 데이터와 이전 학습 기록을 포함한 모든 단어 중 5개를 무작위 출제합니다.</p>
                  </div>
                  <button 
                    onClick={() => startTest('cumulative')} 
                    className={`w-full font-bold py-5 rounded-[1.5rem] shadow-lg transition-all active:scale-[0.98] ${ (totalCumulativeCount > 0) ? 'bg-violet-600 text-white hover:bg-violet-700 shadow-violet-200' : 'bg-slate-100 text-slate-400 cursor-not-allowed'}`}
                    disabled={totalCumulativeCount === 0}
                  >
                    누적 시험 시작 ({totalCumulativeCount}개 중 5개)
                  </button>
                </div>
              </div>
            ) : (
              <div className="bg-white p-8 rounded-[2.5rem] shadow-sm border border-slate-100 min-h-[500px] flex flex-col justify-center text-center relative overflow-hidden">
                {testResults.length === testWords.length ? (
                  <div className="space-y-6 animate-fadeIn">
                    <h2 className="text-2xl font-bold text-slate-800">테스트 종료!</h2>
                    <div className="inline-block px-6 py-2 bg-indigo-50 rounded-full text-indigo-700 font-bold">
                        맞은 개수: {testResults.filter(r => r.isCorrect).length} / {testWords.length}
                    </div>
                    <div className="space-y-2 text-left overflow-y-auto max-h-[350px] pr-2 custom-scrollbar">
                      {testResults.map((r, i) => (
                        <div key={i} className={`p-5 rounded-3xl border ${r.isCorrect ? 'bg-green-50 border-green-100 shadow-sm shadow-green-100' : 'bg-red-50 border-red-100 shadow-sm shadow-red-100'}`}>
                          <div className="flex justify-between font-bold text-slate-800">
                            <span>{r.word}</span>
                            <span className={r.isCorrect ? 'text-green-600' : 'text-red-500'}>{r.isCorrect ? '⭕ 정답' : '❌ 오답'}</span>
                          </div>
                          <p className="text-xs text-slate-500 mt-2 leading-relaxed">{r.feedback}</p>
                        </div>
                      ))}
                    </div>
                    <button onClick={() => setTestMode('none')} className="w-full bg-slate-800 text-white font-bold py-5 rounded-[1.5rem] shadow-md hover:bg-slate-900 transition-all">메뉴로 돌아가기</button>
                  </div>
                ) : (
                  <div className="space-y-8 animate-fadeIn">
                    <div className="absolute top-0 left-0 w-full h-2 bg-slate-50">
                      <div className="h-full bg-gradient-to-r from-indigo-500 to-purple-500 transition-all duration-500 ease-out" style={{ width: `${((testStep + 1) / testWords.length) * 100}%` }} />
                    </div>
                    <div>
                      <div className="text-[10px] font-bold text-slate-300 mb-6 uppercase tracking-widest">Question {testStep + 1} of {testWords.length}</div>
                      <button onClick={() => speakWord(testWords[testStep].word)} className="w-28 h-28 bg-indigo-50 rounded-full flex items-center justify-center mx-auto hover:bg-indigo-100 active:scale-95 group transition-all shadow-sm">
                        <SpeakerWaveIcon className="w-12 h-12 text-indigo-600 group-hover:scale-110 transition-transform" />
                      </button>
                      <p className="text-[10px] text-slate-400 mt-4 uppercase font-bold tracking-tighter">단어 발음을 듣고 스펠링과 뜻을 적으세요</p>
                    </div>
                    <div className="space-y-4 max-w-sm mx-auto">
                      <input type="text" placeholder="Spelling" value={currentTestInput.spelling} onChange={(e) => setCurrentTestInput({...currentTestInput, spelling: e.target.value})} className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-6 py-4 text-center text-xl font-bold outline-none focus:ring-2 focus:ring-indigo-500 transition-all placeholder:text-slate-300" />
                      <input type="text" placeholder="뜻 (한글)" value={currentTestInput.meaning} onChange={(e) => setCurrentTestInput({...currentTestInput, meaning: e.target.value})} className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-6 py-4 text-center text-xl font-bold outline-none focus:ring-2 focus:ring-indigo-500 transition-all placeholder:text-slate-300" />
                    </div>
                    <button onClick={handleNextTest} disabled={isScoring || !currentTestInput.spelling.trim() || !currentTestInput.meaning.trim()} className="w-full max-w-sm mx-auto bg-indigo-600 text-white font-bold py-5 rounded-[1.5rem] shadow-lg flex items-center justify-center gap-2 hover:bg-indigo-700 transition-all disabled:opacity-50 active:scale-[0.98]">
                      {isScoring ? (
                        <>
                          <div className="w-5 h-5 border-3 border-white border-t-transparent rounded-full animate-spin" />
                          AI 채점 중...
                        </>
                      ) : '제출 및 다음 문제'}
                    </button>
                  </div>
                )}
              </div>
            )}
          </div>
        )}

        {activeTab === 'record' && (
          <div className="animate-fadeIn flex flex-col gap-6">
            <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border border-slate-100 text-center space-y-8">
              <div className={`w-28 h-28 rounded-full flex items-center justify-center mx-auto transition-all ${isRecording ? 'bg-red-50 animate-pulse scale-110' : 'bg-indigo-50'}`}>
                <MicrophoneIcon className={`w-14 h-14 ${isRecording ? 'text-red-600' : 'text-indigo-600'}`} />
              </div>
              <div className="space-y-2">
                <h2 className="text-xl font-bold text-slate-800">영어 발음 연습</h2>
                <p className="text-slate-400 text-sm">오늘 학습한 단어를 직접 소리 내어 읽고 확인하세요.</p>
              </div>
              <div className="flex gap-4 justify-center">
                {!isRecording ? (
                  <button onClick={startRecording} className="bg-indigo-600 text-white font-bold px-10 py-5 rounded-[1.5rem] shadow-lg hover:bg-indigo-700 transition-all flex items-center gap-2 active:scale-[0.98]">
                    <MicrophoneIcon className="w-5 h-5" /> 녹음 시작
                  </button>
                ) : (
                  <button onClick={stopRecording} className="bg-red-600 text-white font-bold px-10 py-5 rounded-[1.5rem] shadow-lg hover:bg-red-700 transition-all flex items-center gap-2 active:scale-[0.98]">
                    <StopIcon className="w-5 h-5" /> 녹음 중지
                  </button>
                )}
              </div>
              {audioUrl && !isRecording && (
                <div className="pt-8 border-t border-slate-50 space-y-4">
                  <div className="flex items-center justify-center gap-5">
                    <button onClick={() => new Audio(audioUrl).play()} className="bg-slate-800 text-white font-bold px-8 py-4 rounded-2xl shadow-md flex items-center gap-2 hover:bg-slate-900 transition-all"><PlayIcon className="w-5 h-5" /> 내 녹음 듣기</button>
                    <button onClick={() => setAudioUrl(null)} className="text-slate-400 text-xs font-bold underline hover:text-red-500 transition-colors">지우고 다시 하기</button>
                  </div>
                </div>
              )}
            </div>
          </div>
        )}

        {activeTab === 'settings' && (
          <div className="animate-fadeIn flex flex-col gap-6">
            <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border border-slate-100 space-y-8">
               <div className="flex items-center gap-3 border-b border-slate-50 pb-6">
                 <Cog6ToothIcon className="w-8 h-8 text-indigo-600" />
                 <div>
                   <h2 className="text-xl font-bold text-slate-800">앱 설정</h2>
                   <p className="text-slate-400 text-xs font-medium uppercase tracking-tighter">Sync Configuration</p>
                 </div>
               </div>

               <div className="space-y-4">
                 <div className="space-y-2">
                   <label className="text-xs font-bold text-slate-500 flex items-center gap-2"><LinkIcon className="w-4 h-4" /> 구글 앱스 스크립트(GAS) URL</label>
                   <input 
                    type="text" 
                    value={gasUrl} 
                    onChange={(e) => setGasUrl(e.target.value)}
                    placeholder="https://script.google.com/macros/s/.../exec"
                    className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-5 py-4 text-sm font-mono text-slate-600 outline-none focus:ring-2 focus:ring-indigo-500 transition-all shadow-inner"
                   />
                 </div>
                 <div className="bg-amber-50 border border-amber-100 p-5 rounded-3xl">
                   <p className="text-xs text-amber-800 leading-relaxed">
                     💡 <b>도움말:</b> 시트와 연동되지 않는다면 URL을 다시 확인하고, 시트에 <b>"영어단어"</b>와 <b>"의미"</b>라는 제목의 열이 있는지 확인해주세요. 설정 후 '저장' 버튼을 누르면 즉시 동기화를 시작합니다.
                   </p>
                 </div>
                 <button onClick={saveGasUrl} className="w-full bg-indigo-600 text-white font-bold py-5 rounded-[1.5rem] shadow-lg hover:bg-indigo-700 transition-all active:scale-[0.98]">
                    설정 저장 및 다시 동기화
                 </button>
               </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { WordEntry, DailyRecord, TestResult } from './types';
import { scoreTest } from './services/geminiService';
import { 
  CalendarIcon, 
  PencilSquareIcon, 
  CheckCircleIcon, 
  ArrowPathIcon,
  SpeakerWaveIcon,
  AcademicCapIcon,
  BookOpenIcon,
  SparklesIcon,
  NewspaperIcon,
  MicrophoneIcon,
  StopIcon,
  PlayIcon,
  CloudArrowDownIcon,
  ExclamationCircleIcon,
  Cog6ToothIcon,
  LinkIcon
} from '@heroicons/react/24/outline';

// 사용자 제공 최신 GAS URL
const DEFAULT_GAS_URL = "https://script.google.com/macros/s/AKfycbwqJNte9iEsNvW_5CWwyxkdxYazw7nTQ_cH2W0GYQwqDDWFSReQII1xLXwXNSoxOfuGIA/exec";

const getTodayString = () => {
  const now = new Date();
  const offset = now.getTimezoneOffset() * 60000;
  return new Date(now.getTime() - offset).toISOString().split('T')[0];
};

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'study' | 'test' | 'record' | 'settings'>('study');
  const [gasUrl, setGasUrl] = useState<string>(DEFAULT_GAS_URL);
  const [testMode, setTestMode] = useState<'none' | 'today' | 'cumulative'>('none');
  const [todayRecord, setTodayRecord] = useState<DailyRecord>({
    date: getTodayString(),
    page: '',
    words: Array(13).fill({ word: '', meaning: '' }),
    newsContent: '',
    isCompleted: false,
  });
  const [history, setHistory] = useState<DailyRecord[]>([]);
  const [sheetWords, setSheetWords] = useState<WordEntry[]>([]);
  const [isLoadingSheet, setIsLoadingSheet] = useState(false);
  const [loadError, setLoadError] = useState<string | null>(null);

  const [testWords, setTestWords] = useState<WordEntry[]>([]);
  const [testStep, setTestStep] = useState(0);
  const [testResults, setTestResults] = useState<TestResult[]>([]);
  const [currentTestInput, setCurrentTestInput] = useState({ spelling: '', meaning: '' });
  const [isScoring, setIsScoring] = useState(false);

  // Recording states
  const [isRecording, setIsRecording] = useState(false);
  const [audioUrl, setAudioUrl] = useState<string | null>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);

  const calendarData = useMemo(() => {
    const now = new Date();
    const year = now.getFullYear();
    const month = now.getMonth();
    const firstDay = new Date(year, month, 1).getDay();
    const lastDate = new Date(year, month + 1, 0).getDate();
    const days = [];
    for (let i = 0; i < firstDay; i++) days.push(null);
    for (let i = 1; i <= lastDate; i++) {
      days.push({
        day: i,
        dateStr: `${year}-${String(month + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`
      });
    }
    return { days, month: month + 1, year };
  }, []);

  // 구글 시트 데이터 로드 및 파싱 로직 (인덱스 기반 매핑 추가)
  const fetchSheetData = async (targetUrl: string = gasUrl) => {
    if (!targetUrl || !targetUrl.startsWith('https://')) return;

    setIsLoadingSheet(true);
    setLoadError(null);
    try {
      const url = `${targetUrl}?action=read&t=${Date.now()}`;
      const response = await fetch(url);

      if (!response.ok) throw new Error(`서버 응답 오류: ${response.status}`);

      const rawData = await response.json();

      // 데이터가 객체 감싸기 형태인지 확인
      const dataArray = Array.isArray(rawData) ? rawData : (rawData.data && Array.isArray(rawData.data) ? rawData.data : []);

      if (dataArray.length > 0) {
        const parsedWords: WordEntry[] = dataArray
          .map((item: any) => {
            let word = "";
            let meaning = "";

            if (Array.isArray(item)) {
              // 배열 형태인 경우 (A:날짜, B:페이지, C:영어단어, D:의미) -> 2번, 3번 인덱스
              word = item[2] || "";
              meaning = item[3] || "";
            } else if (typeof item === 'object') {
              // 객체 형태인 경우 헤더 이름으로 매핑
              word = item["영어단어"] || item.영어단어 || item.word || item.Word || "";
              meaning = item["의미"] || item.의미 || item.meaning || item.Meaning || "";
            }

            return {
              word: String(word).trim(),
              meaning: String(meaning).trim()
            };
          })
          .filter((w) => {
            const skipLabels = ["영어단어", "word", "의미", "meaning", "english"];
            return (
              w.word.length > 1 && 
              w.meaning.length >= 1 && 
              !skipLabels.includes(w.word.toLowerCase())
            );
          });

        // 중복 제거
        const uniqueMap = new Map();
        parsedWords.forEach(w => uniqueMap.set(w.word.toLowerCase(), w));
        const finalWords = Array.from(uniqueMap.values());

        setSheetWords(finalWords);
        console.log("시트 동기화 성공:", finalWords.length, "개 단어 로드됨.");
      } else {
        console.warn("시트에 데이터가 없거나 형식이 다릅니다.");
      }
    } catch (error: any) {
      console.error("Fetch Error:", error);
      setLoadError("시트 데이터를 불러오지 못했습니다. 설정에서 URL을 확인하세요.");
    } finally {
      setIsLoadingSheet(false);
    }
  };

  useEffect(() => {
    const savedUrl = localStorage.getItem('study_gas_url');
    const finalUrl = savedUrl || DEFAULT_GAS_URL;
    setGasUrl(finalUrl);
    fetchSheetData(finalUrl);

    const savedHistory = localStorage.getItem('study_history');
    if (savedHistory) {
      const parsed: DailyRecord[] = JSON.parse(savedHistory);
      setHistory(parsed);
      loadRecordForDate(todayRecord.date, parsed);
    }
  }, []);

  const loadRecordForDate = (dateStr: string, currentHistory: DailyRecord[]) => {
    const existing = currentHistory.find(r => r.date === dateStr);
    if (existing) {
      setTodayRecord(existing);
    } else {
      setTodayRecord({
        date: dateStr,
        page: '',
        words: Array(13).fill({ word: '', meaning: '' }),
        newsContent: '',
        isCompleted: false,
      });
    }
  };

  const saveGasUrl = () => {
    const cleanUrl = gasUrl.trim();
    if (!cleanUrl.startsWith('https://script.google.com')) {
      alert("올바른 구글 앱스 스크립트 실행 URL이 아닙니다.");
      return;
    }
    localStorage.setItem('study_gas_url', cleanUrl);
    alert("설정이 저장되었습니다.");
    fetchSheetData(cleanUrl);
  };

  const handleDateChange = (newDate: string) => {
    loadRecordForDate(newDate, history);
  };

  const handleWordChange = (index: number, field: keyof WordEntry, value: string) => {
    const newWords = [...todayRecord.words];
    newWords[index] = { ...newWords[index], [field]: value };
    setTodayRecord({ ...todayRecord, words: newWords });
  };

  const submitStudy = async () => {
    const updatedRecord = { ...todayRecord, isCompleted: true };
    setTodayRecord(updatedRecord);
    const newHistory = [...history.filter(r => r.date !== todayRecord.date), updatedRecord];
    setHistory(newHistory);
    localStorage.setItem('study_history', JSON.stringify(newHistory));

    // 시트 전송용 데이터 구성
    const payload = {
      action: "insert",
      date: todayRecord.date,
      page: todayRecord.page,
      news: todayRecord.newsContent,
      status: "학습완료",
      words: todayRecord.words.filter(w => w.word.trim() !== "")
    };

    try {
      await fetch(gasUrl, {
        method: "POST",
        mode: "no-cors", 
        headers: { "Content-Type": "text/plain" },
        body: JSON.stringify(payload),
      });
      alert('시트에 기록되었습니다!');
      // 전송 후 데이터 갱신
      setTimeout(() => fetchSheetData(gasUrl), 2000);
    } catch (error) {
      alert('시트 전송 실패. 네트워크를 확인하세요.');
    }
  };

  const startTest = async (mode: 'today' | 'cumulative') => {
    let sourceWords: WordEntry[] = [];

    if (mode === 'today') {
      sourceWords = todayRecord.words.filter(w => w && w.word?.trim() !== "" && w.meaning?.trim() !== "");
      if (sourceWords.length === 0) {
        alert('오늘 학습한 단어가 없습니다.');
        return;
      }
    } else {
      // 누적 단어 소스 (시트 데이터 우선)
      sourceWords = sheetWords;
      if (sourceWords.length === 0) {
        // 시트 데이터가 없으면 로컬 기록이라도 가져옴
        const historyWords = history.flatMap(h => h.words || []).filter(w => w.word && w.word.trim() !== "");
        const uniqueMap = new Map();
        historyWords.forEach(w => uniqueMap.set(w.word.toLowerCase().trim(), w));
        sourceWords = Array.from(uniqueMap.values());
      }

      if (sourceWords.length === 0) {
        alert('테스트할 누적 단어가 없습니다. 시트 동기화를 확인하세요.');
        setActiveTab('settings');
        return;
      }
    }

    const shuffled = [...sourceWords].sort(() => 0.5 - Math.random());
    const finalWords = mode === 'today' ? shuffled : shuffled.slice(0, Math.min(5, shuffled.length));

    setTestWords(finalWords);
    setTestStep(0);
    setTestResults([]);
    setCurrentTestInput({ spelling: '', meaning: '' });
    setTestMode(mode);
    setActiveTab('test');
  };

  const speakWord = (word: string) => {
    const utterance = new SpeechSynthesisUtterance(word);
    utterance.lang = 'en-US';
    window.speechSynthesis.speak(utterance);
  };

  const handleNextTest = async () => {
    if (isScoring) return;
    setIsScoring(true);
    const target = testWords[testStep];
    const score = await scoreTest(target.word, target.meaning, currentTestInput.spelling, currentTestInput.meaning);

    const result: TestResult = {
      word: target.word,
      userSpelling: currentTestInput.spelling,
      userMeaning: currentTestInput.meaning,
      isCorrect: score.isCorrect,
      feedback: score.feedback
    };

    setTestResults([...testResults, result]);
    setIsScoring(false);

    if (testStep < testWords.length - 1) {
      setTestStep(testStep + 1);
      setCurrentTestInput({ spelling: '', meaning: '' });
    }
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];
      mediaRecorder.ondataavailable = (e) => { if (e.data.size > 0) audioChunksRef.current.push(e.data); };
      mediaRecorder.onstop = () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/wav' });
        setAudioUrl(URL.createObjectURL(audioBlob));
      };
      mediaRecorder.start();
      setIsRecording(true);
    } catch (err) { alert("마이크 권한이 필요합니다."); }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      mediaRecorderRef.current.stream.getTracks().forEach(track => track.stop());
    }
  };

  return (
    <div className="min-h-screen pb-24 max-w-2xl mx-auto p-4 flex flex-col gap-6">
      <header className="flex flex-col gap-1 items-center py-6 bg-white rounded-3xl shadow-sm border border-slate-100 relative overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-indigo-500 via-purple-500 to-indigo-500 animate-gradient-x" />
        <div className="absolute top-4 right-4 flex items-center gap-2">
            <div className={`flex items-center gap-1 text-[10px] font-bold px-2 py-1 rounded-full ${loadError ? 'bg-red-50 text-red-500' : 'bg-green-50 text-green-600'}`}>
                {loadError ? <ExclamationCircleIcon className="w-3 h-3" /> : <div className="w-1.5 h-1.5 bg-green-500 rounded-full" />}
                {loadError ? '연결 오류' : `${sheetWords.length}단어`}
            </div>
            <button onClick={() => fetchSheetData()} className={`p-1.5 rounded-full hover:bg-slate-100 transition-all ${isLoadingSheet ? 'animate-spin' : ''}`}>
                <CloudArrowDownIcon className="w-5 h-5 text-indigo-400" />
            </button>
        </div>
        <h1 className="text-2xl font-bold text-indigo-600 flex items-center gap-2">
          <AcademicCapIcon className="w-8 h-8" />
          영어 학습 기록장
        </h1>
        <p className="text-slate-400 text-xs font-medium uppercase tracking-widest">Smart Vocabulary Master</p>
      </header>

