                <MicrophoneIcon className={`w-14 h-14 ${isRecording ? 'text-red-600' : 'text-indigo-600'}`} />
              </div>
              <h2 className="text-xl font-bold text-slate-800">영어 발음 연습</h2>
              <div className="flex gap-4 justify-center">
                {!isRecording ? (
                  <button onClick={startRecording} className="bg-indigo-600 text-white font-bold px-10 py-5 rounded-[1.5rem] shadow-lg hover:bg-indigo-700 transition-all active:scale-95 flex items-center gap-2">
                    <MicrophoneIcon className="w-5 h-5" /> 녹음 시작
                  </button>
                ) : (
                  <button onClick={stopRecording} className="bg-red-600 text-white font-bold px-10 py-5 rounded-[1.5rem] shadow-lg hover:bg-red-700 transition-all active:scale-95 flex items-center gap-2">
                    <StopIcon className="w-5 h-5" /> 녹음 중지
                  </button>
                )}
              </div>
              {audioUrl && !isRecording && (
                <div className="pt-8 border-t border-slate-50 space-y-4 flex flex-col items-center">
                  <button onClick={() => new Audio(audioUrl).play()} className="bg-slate-800 text-white font-bold px-8 py-4 rounded-2xl shadow-md flex items-center gap-2 hover:bg-slate-900 transition-all"><PlayIcon className="w-5 h-5" /> 내 녹음 듣기</button>
                  <button onClick={() => setAudioUrl(null)} className="text-slate-400 text-xs font-bold underline hover:text-red-500">삭제하고 다시하기</button>
                </div>
              )}
            </div>
          </div>
        )}

        {activeTab === 'settings' && (
          <div className="animate-fadeIn space-y-6">
            <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border border-slate-100 space-y-8">
               <h2 className="text-xl font-bold text-slate-800 flex items-center gap-2"><Cog6ToothIcon className="w-6 h-6 text-indigo-600" /> 앱 설정</h2>
               <div className="space-y-4">
                 <div className="space-y-2">
                   <label className="text-xs font-bold text-slate-500">GAS 배포 URL</label>
                   <input 
                    type="text" 
                    value={gasUrl} 
                    onChange={(e) => setGasUrl(e.target.value)}
                    placeholder="https://script.google.com/macros/s/.../exec"
                    className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-5 py-4 text-xs font-mono outline-none focus:ring-2 focus:ring-indigo-500 shadow-inner"
                   />
                 </div>
                 <div className="bg-indigo-50 p-5 rounded-3xl border border-indigo-100">
                   <h3 className="text-xs font-bold text-indigo-800 mb-2">💡 시트 연동 가이드</h3>
                   <p className="text-[11px] text-indigo-700 leading-relaxed font-medium">
                     1. 구글 시트의 Apps Script에 코드를 붙여넣고 배포하세요.<br/>
                     2. 배포 시 '웹 앱', '모든 사용자' 권한을 주어야 합니다.<br/>
                     3. 시트의 C열(3번째)이 영어단어, D열(4번째)이 의미입니다.
                   </p>
                 </div>
                 <button onClick={saveGasUrl} className="w-full bg-indigo-600 text-white font-bold py-5 rounded-[1.5rem] shadow-lg hover:bg-indigo-700 transition-all active:scale-95">설정 저장 및 동기화</button>
               </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

