payload.text:
구글 앱스 스크립트(Google Apps Script, 이하 GAS)로 이 앱을 배포하려면, 일반적인 웹 개발 환경(Vite/Vercel)과는 조금 다른 방식이 필요합니다. GAS는 하나의 HTML 파일 안에 모든 자바스크립트와 CSS가 포함된 형태를 가장 선호합니다.

중학생 개발자인 당신이 **복잡한 빌드 과정 없이 바로 복사해서 붙여넣을 수 있도록** 코드를 GAS 전용으로 최적화해 드릴게요.

### 1단계: 구글 시트 및 스크립트 준비

1.  사용 중인 **구글 시트**를 엽니다.
2.  상단 메뉴에서 **확장 프로그램 > Apps Script**를 클릭합니다.
3.  프로젝트 이름을 `Smart English Study Log`로 바꿉니다.

---

### 2단계: 코드 작성 (복사 & 붙여넣기)

#### 1. Code.gs (서버 측 코드)
기존 `Code.gs` 내용을 모두 지우고 아래 코드를 복사해 넣으세요. 이 코드는 HTML 파일을 화면에 그려주고, 구글 시트와 통신하는 역할을 합니다.

```javascript
/**
 * 웹 앱 접속 시 실행되는 함수
 */
function doGet() {
  return HtmlService.createTemplateFromFile('index')
    .evaluate()
    .setTitle('Smart English Study Log')
    .addMetaTag('viewport', 'width=device-width, initial-scale=1')
    .setXFrameOptionsMode(HtmlService.XFrameOptionsMode.ALLOWALL);
}

/**
 * 환경 변수(API_KEY)를 클라이언트에 안전하게 전달
 * (Vercel의 process.env 역할을 대신함)
 */
function getApiKey() {
  // 여기에 실제 본인의 Gemini API Key를 적으세요!
  return "YOUR_GEMINI_API_KEY_HERE"; 
}

/**
 * 데이터를 시트에 저장하는 함수
 */
function doPost(e) {
  const data = JSON.parse(e.postData.contents);
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getActiveSheet();

  if (data.action === "insert") {
    data.words.forEach(word => {
      sheet.appendRow([
        data.date,
        data.page,
        word.word,
        word.meaning,
        data.news,
        data.status
      ]);
    });
    return ContentService.createTextOutput("Success");
  }
}

/**
 * 시트 데이터를 읽어오는 함수 (누적 테스트용)
 */
function readSheetData() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getActiveSheet();
  const data = sheet.getDataRange().getValues();
  return data; // 배열 형태로 반환
}
```

#### 2. index.html (클라이언트 측 코드)
Apps Script 메뉴에서 **파일 옆의 + 버튼 > HTML**을 눌러 이름을 `index`로 만들고 아래 내용을 붙여넣으세요. (기존 `App.tsx`, `index.tsx`, `geminiService.ts` 등을 하나로 합친 버전입니다.)

```html
<!DOCTYPE html>
<html lang="ko">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Smart English Study Log</title>
    <script src="https://cdn.tailwindcss.com"></script>
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700&display=swap" rel="stylesheet">
    <style>
        body { font-family: 'Inter', sans-serif; }
        .animate-fadeIn { animation: fadeIn 0.3s ease-in-out; }
        @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
    </style>
    <!-- React 및 필요한 라이브러리 로드 (esm.sh 사용) -->
    <script type="importmap">
    {
      "imports": {
        "react": "https://esm.sh/react@19.0.0",
        "react-dom/client": "https://esm.sh/react-dom@19.0.0/client",
        "@google/genai": "https://esm.sh/@google/genai@1.38.0",
        "@heroicons/react/24/outline": "https://esm.sh/@heroicons/react@2.0.18/24/outline"
      }
    }
    </script>
</head>
<body class="bg-slate-50">
    <div id="root"></div>

    <script type="module">
        import React, { useState, useEffect, useMemo, useRef } from 'react';
        import { createRoot } from 'react-dom/client';
        import { GoogleGenAI, Type } from "@google/genai";
        import * as Icons from "@heroicons/react/24/outline";

        // --- GAS 연동 헬퍼 ---
        const runGas = (funcName, ...args) => {
            return new Promise((resolve, reject) => {
                google.script.run
                    .withSuccessHandler(resolve)
                    .withFailureHandler(reject)[funcName](...args);
            });
        };

        // --- Gemini Service ---
        const getAiClient = async () => {
            const apiKey = await runGas('getApiKey');
            return new GoogleGenAI({ apiKey });
        };

        const scoreTest = async (originalWord, originalMeaning, userSpelling, userMeaning) => {
            try {
                const ai = await getAiClient();
                const response = await ai.models.generateContent({
                    model: "gemini-3-flash-preview",
                    contents: `단어: ${originalWord}, 의미: ${originalMeaning}, 학생답: ${userSpelling}(뜻: ${userMeaning}). 채점해줘.`,
                    config: {
                        responseMimeType: "application/json",
                        responseSchema: {
                            type: "OBJECT",
                            properties: {
                                isCorrect: { type: "BOOLEAN" },
                                feedback: { type: "STRING" }
                            },
                            required: ["isCorrect", "feedback"]
                        }
                    }
                });
                return JSON.parse(response.text);
            } catch (error) {
                return { isCorrect: originalWord.toLowerCase() === userSpelling.toLowerCase(), feedback: "AI 연결 실패(수동채점)" };
            }
        };

        // --- App Component ---
        const App = () => {
            const [activeTab, setActiveTab] = useState('study');
            const [todayRecord, setTodayRecord] = useState({
                date: new Date().toISOString().split('T')[0],
                page: '',
                words: Array(13).fill({ word: '', meaning: '' }),
                newsContent: '',
                isCompleted: false
            });
            const [sheetWords, setSheetWords] = useState([]);
            const [isLoading, setIsLoading] = useState(false);

            // 데이터 로드
            useEffect(() => {
                loadData();
            }, []);

            const loadData = async () => {
                const data = await runGas('readSheetData');
                if (data && data.length > 1) {
                    const parsed = data.slice(1).map(row => ({ word: row[2], meaning: row[3] }));
                    setSheetWords(parsed);
                }
            };

            const submitStudy = async () => {
                const filledWords = todayRecord.words.filter(w => w.word.trim() !== "");
                if (filledWords.length === 0) return alert("단어를 입력하세요!");

                setIsLoading(true);
                const payload = {
                    action: "insert",
                    date: todayRecord.date,
                    page: todayRecord.page,
